Below is a complete Terraform HCL program that configures a weighted routing policy in Route 53 to split users between two RDS database instances that are replicas of a main RDS database instance. The zone is named "main", the original database instance is named "primary", and the two replicas are named "replica-1" and "replica-2".

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_route53_zone" "zone_main" {
  name = "main.example.com"
}

resource "aws_db_instance" "db_instance_primary" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  username = "admin"
  password = "password"
  db_name = "mydatabase"
}

resource "aws_db_instance" "db_instance_replica_1" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  username = "admin"
  password = "password"
  db_name = "mydatabase"
  replicate_source_db = aws_db_instance.db_instance_primary.identifier
}

resource "aws_db_instance" "db_instance_replica_2" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  username = "admin"
  password = "password"
  db_name = "mydatabase"
  replicate_source_db = aws_db_instance.db_instance_primary.identifier
}

resource "aws_route53_record" "record_weighted_routing_primary" {
  zone_id = aws_route53_zone.zone_main.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 10
  }

  set_identifier = "primary"
  records        = [aws_db_instance.db_instance_primary.endpoint]
}

resource "aws_route53_record" "record_weighted_routing_replica_1" {
  zone_id = aws_route53_zone.zone_main.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  set_identifier = "replica-1"
  records        = [aws_db_instance.db_instance_replica_1.endpoint]
}

resource "aws_route53_record" "record_weighted_routing_replica_2" {
  zone_id = aws_route53_zone.zone_main.zone_id
  name    = "db.main.example.com"
  type    = "CNAME"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  set_identifier = "replica-2"
  records        = [aws_db_instance.db_instance_replica_2.endpoint]
}
```

This Terraform configuration creates:
1. A Route 53 hosted zone named "main.example.com".
2. A primary RDS database instance.
3. Two replica RDS database instances that replicate from the primary instance.
4. Three Route 53 records with weighted routing policies to distribute traffic between the primary and replica instances.

