Below is the complete Terraform HCL program that meets the requirements specified in the prompt. This program sets up an Elastic Beanstalk worker environment for running batch processing jobs, including the necessary IAM roles, S3 bucket, SQS queue, and Elastic Beanstalk application.

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 instances in Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier",
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWorkerTier",
    "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess",
    "arn:aws:iam::aws:policy/AmazonSQSFullAccess"
  ]
}

# IAM Instance Profile associated with the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# S3 Bucket for storing application artifacts
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
  acl    = "private"
}

# Object stored in the S3 bucket
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.bucket
  key    = "example-object.zip"
  source = "path/to/example-object.zip"
}

# SQS Queue for batch job communication
resource "aws_sqs_queue" "batch_job_queue" {
  name = "batch_job_queue"
}

# Elastic Beanstalk Application for batch processing
resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name = "batch_job_app"
}

# Application Version linked to the S3 object
resource "aws_elastic_beanstalk_application_version" "version" {
  application = aws_elastic_beanstalk_application.batch_job_app.name
  bucket      = aws_s3_bucket.sampleapril26426.bucket
  key         = aws_s3_object.examplebucket_object.key
  name        = "version"
}

# Elastic Beanstalk Environment for batch processing
resource "aws_elastic_beanstalk_environment" "batch_job_env" {
  name                = "batch-job-env"
  application         = aws_elastic_beanstalk_application.batch_job_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
  version_label       = aws_elastic_beanstalk_application_version.version.name
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "1"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_ec2_role.arn
  }
}
```

