provider "aws" {
  region = "us-west-2"
}

# IAM Role for Route53 operations
resource "aws_iam_role" "route53_weighted_routing_role" {
  name = "route53-weighted-routing-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Route53 operations
resource "aws_iam_policy" "route53_weighted_routing_policy" {
  name = "route53-weighted-routing-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "route53:ChangeResourceRecordSets",
          "route53:GetHostedZone",
          "route53:ListHostedZonesByName"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_route53_policy_to_role" {
  policy_arn = aws_iam_policy.route53_weighted_routing_policy.arn
  role       = aws_iam_role.route53_weighted_routing_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "example_app" {
  name        = "example-app"
  description = "Example Elastic Beanstalk Application"
}

# Elastic Beanstalk Environment for Blue Deployment
