Below is a complete Terraform HCL program that configures a blue/green deployment with Route 53 resources to direct traffic to two separate environments connected to a shared RDS database. It includes IAM roles, RDS instance, Route 53 zone, and health checks.

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Instance Profile for EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Shared RDS database for both environments
resource "aws_db_instance" "myapp_db" {
  identifier         = "myapp-db"
  instance_class     = "db.t3.micro"
  engine             = "mysql"
  engine_version     = "8.0"
  username           = "admin"
  password           = "password"
  allocated_storage  = 20
  skip_final_snapshot = true
}

# Route 53 Hosted Zone for DNS management
resource "aws_route53_zone" "myapp_zone" {
  name = "myapp.com"
}

# DNS Record for the blue environment
resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "blue.myapp.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.1"]
}

# DNS Record for the green environment
resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "green.myapp.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.2"]
}

# Health Check for the blue environment
resource "aws_route53_health_check" "blue_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = "blue.myapp.com"
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

# Health Check for the green environment
resource "aws_route53_health_check" "green_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = "green.myapp.com"
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

# Failover Routing Policy Record
resource "aws_route53_record" "failover_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue_health_check.id

  records = ["192.168.1.1"]

  depends_on = [aws_route53_health_check.blue_health_check]
}

resource "aws_route53_record" "failover_record_secondary" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.green_health_check.id

  records = ["192.168.1.2"]

  depends_on = [aws_route53_health_check.green_health_check]
}
```

This Terraform configuration sets up the necessary resources for a blue/green deployment with Route 53, including IAM roles, an RDS database, and Route 53 records with health checks and failover routing policies.

