### Description
This Terraform configuration sets up an Elastic Beanstalk application with the necessary IAM roles and policies. It includes:

1. **IAM Role**: An IAM role (`elastic_beanstalk_service_role`) that Elastic Beanstalk will assume to manage resources.
2. **IAM Policy**: An IAM policy (`elastic_beanstalk_policy`) that defines the permissions required by the Elastic Beanstalk service.
3. **IAM Role Policy Attachment**: Attaches the IAM policy to the IAM role.
4. **Elastic Beanstalk Application**: Creates an Elastic Beanstalk application (`my_elastic_beanstalk_app`) with an application version lifecycle configuration.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_service_role" {
  name = "elastic_beanstalk_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Elastic Beanstalk
resource "aws_iam_policy" "elastic_beanstalk_policy" {
  name        = "elastic_beanstalk_policy"
  description = "Policy for Elastic Beanstalk to manage resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "s3:*",
          "sns:*",
          "cloudformation:*",
          "dynamodb:*",
          "rds:*",
          "logs:*",
          "iam:PassRole"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_elastic_beanstalk_policy_to_role" {
  policy_arn = aws_iam_policy.elastic_beanstalk_policy.arn
  role       = aws_iam_role.elastic_beanstalk_service_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_elastic_beanstalk_app" {
  name = "my_elastic_beanstalk_app"

  appversion_lifecycle {
    service_role          = aws_iam_role.elastic_beanstalk_service_role.arn
    max_count             = 128
    delete_source_from_s3 = true
  }
}
```

