### Description
This Terraform configuration sets up an Elastic Beanstalk application with an application version lifecycle. The application version will be retained for 5 days before being automatically deleted. The configuration includes creating an S3 bucket to store the application version, an IAM role with necessary permissions, and a Lambda function triggered by a CloudWatch event to manage the lifecycle of the application version.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elastic_beanstalk_service_role" {
  name = "elastic_beanstalk_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "elastic_beanstalk_policy" {
  name        = "elastic_beanstalk_policy"
  description = "Policy for Elastic Beanstalk to delete application versions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::my-elastic-beanstalk-bucket/*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elastic_beanstalk_policy" {
  role       = aws_iam_role.elastic_beanstalk_service_role.name
  policy_arn = aws_iam_policy.elastic_beanstalk_policy.arn
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-elastic-beanstalk-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true
    prefix  = ""
    expiration {
      days = 5
    }
  }
}

resource "aws_s3_object" "my_s3_object" {
  bucket = aws_s3_bucket.my_s3_bucket.bucket
  key    = "my-application-version.zip"
  source = "path/to/my-application-version.zip"
}

resource "aws_elastic_beanstalk_application" "my_elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role          = aws_iam_role.elastic_beanstalk_service_role.arn
    max_age_in_days       = 5
    delete_source_from_s3 = true
  }
}

resource "aws_elastic_beanstalk_application_version" "my_elastic_beanstalk_app_version" {
  application = aws_elastic_beanstalk_application.my_elastic_beanstalk_app.name
  bucket      = aws_s3_bucket.my_s3_bucket.bucket
  key         = aws_s3_object.my_s3_object.key
  name        = "my-application-version"
}

resource "aws_lambda_function" "manage_app_version_lifecycle" {
  function_name = "manage_app_version_lifecycle"
  role          = aws_iam_role.elastic_beanstalk_service_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "path/to/lambda_function.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.my_s3_bucket.bucket
    }
  }
}

resource "aws_lambda_permission" "allow_cloudwatch_to_trigger_lambda" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.manage_app_version_lifecycle.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_trigger.arn
}

resource "aws_cloudwatch_event_rule" "daily_trigger" {
  name                = "daily-trigger"
  schedule_expression = "cron(0 0 * * ? *)"
}

resource "aws_cloudwatch_event_target" "trigger_lambda" {
  rule      = aws_cloudwatch_event_rule.daily_trigger.name
  target_id = "TriggerLambda"
  arn       = aws_lambda_function.manage_app_version_lifecycle.arn
}

resource "aws_cloudwatch_event_permission" "allow_lambda_invocation" {
  statement_id  = "AllowLambdaInvocation"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.manage_app_version_lifecycle.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_trigger.arn
}
```

This Terraform configuration sets up the necessary resources to manage the lifecycle of an Elastic Beanstalk application version, ensuring that versions are retained for 5 days before being automatically deleted.

