### Description
This Terraform configuration creates an AWS CodeBuild project with an example IAM role, a GitHub source, an S3 bucket for artifacts, and an S3 bucket for caching. The IAM role is granted necessary permissions to interact with the specified S3 buckets and other AWS services.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_example_role" {
  name = "codebuild-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Role Policy for CodeBuild
resource "aws_iam_role_policy" "codebuild_example_role_policy" {
  role = aws_iam_role.codebuild_example_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
        ]
        Resource = [
          "*"
        ]
      },
    ]
  })
}

# S3 Bucket for Artifacts
resource "aws_s3_bucket" "codebuild_artifact_bucket" {
  bucket = "codebuild-artifact-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# S3 Bucket for Cache
resource "aws_s3_bucket" "codebuild_cache_bucket" {
  bucket = "codebuild-cache-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random String for Unique Bucket Names
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild Project"
  service_role  = aws_iam_role.codebuild_example_role.arn

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.codebuild_artifact_bucket.bucket}/artifacts"
