```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot Execution
resource "aws_iam_role" "lex_bot_execution_role" {
  name = "lex_bot_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# Attach necessary policy to the IAM role for Lex bot execution
resource "aws_iam_role_policy_attachment" "attach_lex_policy_to_role" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonLexRunBotsOnly"
  role       = aws_iam_role.lex_bot_execution_role.name
}

# Slot type for pizza size
resource "aws_lex_slot_type" "pizza_size_slot_type" {
  name = "PizzaSize"

  enumeration_value {
    value = "Small"
  }

  enumeration_value {
    value = "Medium"
  }

  enumeration_value {
    value = "Large"
  }
}

# Slot type for pizza topping
