  name = "PizzaTopping"

  enumeration_value {
    value = "Pepperoni"
  }

  enumeration_value {
    value = "Mushrooms"
  }

  enumeration_value {
    value = "Onions"
  }
}

# Intent for ordering pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name = "OrderPizza"

  sample_utterances = [
    "I want a {PizzaSize} pizza",
    "Order {PizzaSize} pizza with {PizzaTopping}"
  ]

  slot {
    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = aws_lex_slot_type.pizza_size_slot_type.name
  }

  slot {
    name            = "PizzaTopping"
    slot_constraint = "Required"
    slot_type       = aws_lex_slot_type.pizza_topping_slot_type.name
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  follow_up_prompt {
    prompt {
      max_attempts = 2
    }
  }
}

# Main Lex bot for ordering pizza
