### Description
This Terraform configuration sets up a Kinesis Firehose Delivery Stream with an extended S3 Destination, including dynamic partitioning. It includes the necessary IAM roles and policies to allow the Firehose delivery stream to write to an S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Firehose to access S3
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy granting S3 access permissions to the Firehose role
resource "aws_iam_policy" "firehose_s3_access_policy" {
  name        = "firehose_s3_access_policy"
  description = "Policy to allow Kinesis Firehose to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the S3 access policy to the Firehose role
resource "aws_iam_role_policy_attachment" "attach_firehose_s3_policy" {
  policy_arn = aws_iam_policy.firehose_s3_access_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# S3 Bucket for the Firehose Delivery Stream
resource "aws_s3_bucket" "firehose_s3_bucket" {
  bucket = "firehose-delivery-stream-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

# Random string to ensure unique bucket name
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose Delivery Stream with Extended S3 Destination
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose_delivery_stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    bucket_arn = aws_s3_bucket.firehose_s3_bucket.arn

    buffering_size = 64

    dynamic_partitioning_configuration {
      enabled = true
    }

    prefix              = "data/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/"
    error_output_prefix = "errors/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/hour=!{timestamp:HH}/!{firehose:error-output-type}/"
  }
}
```

This configuration creates an IAM role and policy that allow the Kinesis Firehose Delivery Stream to write to an S3 bucket. It also sets up the S3 bucket and the Kinesis Firehose Delivery Stream with dynamic partitioning enabled.

