This Terraform configuration sets up a Kinesis Firehose Delivery Stream with an OpenSearch destination. It includes the creation of an IAM role with the necessary permissions, an IAM policy, and the attachment of the policy to the role. Finally, it configures the Kinesis Firehose Delivery Stream to deliver data to OpenSearch.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kinesis Firehose to deliver data to OpenSearch
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose-delivery-stream-policy"
  description = "Policy for Kinesis Firehose to deliver data to OpenSearch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomains",
          "es:DescribeElasticsearchDomainConfig",
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# S3 Bucket for backup
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose Delivery Stream with OpenSearch destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = "arn:aws:es:us-west-2:123456789012:domain/my-opensearch-domain"
    index_name = "firehose-index"
    role_arn   = aws_iam_role.firehose_delivery_stream_role.arn

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_interval = 300
      buffering_size     = 5
      compression_format = "UNCOMPRESSED"
    }
  }
}
```

### Notes
- Ensure that the OpenSearch domain ARN (`domain_arn`) is correctly configured and accessible.
- The IAM policy should grant the necessary permissions for Kinesis Firehose to deliver data to OpenSearch.
- The S3 bucket name is generated with a random suffix to ensure uniqueness. Adjust the bucket name as needed.
- The region and other settings can be customized based on your specific requirements.

