resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose_delivery_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Role Policy for Kinesis Firehose
resource "aws_iam_role_policy" "firehose_delivery_policy" {
  name = "firehose_delivery_policy"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.backup_bucket.arn,
          "${aws_s3_bucket.backup_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogDelivery",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:PutLogEventsBatch",
          "logs:UpdateLogDelivery"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# S3 Bucket for Backup
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random String for S3 Bucket Name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose Delivery Stream with HTTP Endpoint
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "firehose-http-endpoint-stream"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url                = "https://aws-api.newrelic.com/firehose/v1"
    name               = "New Relic"
    access_key         = "my-key"
    buffering_size     = 15
    buffering_interval = 600
    role_arn           = aws_iam_role.firehose_delivery_role.arn
    s3_backup_mode     = "FailedDataOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 10
      buffering_interval = 400
      compression_format = "GZIP"
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `firehose_delivery_role` is created with a trust policy allowing Kinesis Firehose to assume the role.
3. **IAM Role Policy**: A policy is attached to the IAM role that grants permissions for S3 operations and CloudWatch Logs.
4. **S3 Bucket**: An S3 bucket named `firehose-backup-bucket-{random_string}` is created to store backup data.
5. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream is created with an HTTP endpoint destination. The stream is configured to send data to the specified URL and back up failed data to the S3 bucket.

