  vpc_id            = aws_vpc.kinesis_firehose_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Security Group for Kinesis Firehose
resource "aws_security_group" "kinesis_firehose_sg" {
  vpc_id = aws_vpc.kinesis_firehose_vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
