### Description
This Terraform configuration sets up a Kinesis Firehose Delivery Stream with an extended S3 Destination. It includes the necessary IAM roles and policies to allow the Firehose delivery stream to access the S3 bucket. The configuration ensures that all required resources are created and properly linked.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Kinesis Firehose to access S3
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy granting Firehose permissions to access S3
resource "aws_iam_policy" "firehose_s3_access_policy" {
  name = "firehose_s3_access_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.firehose_destination_bucket.arn}",
          "${aws_s3_bucket.firehose_destination_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach the S3 access policy to the Firehose role
resource "aws_iam_role_policy_attachment" "attach_firehose_s3_policy" {
  policy_arn = aws_iam_policy.firehose_s3_access_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# S3 bucket where Firehose will deliver data
resource "aws_s3_bucket" "firehose_destination_bucket" {
  bucket = "firehose-destination-bucket-${random_string.suffix.result}"
}

# Random string to ensure unique bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose delivery stream configured with S3 destination
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    bucket_arn = aws_s3_bucket.firehose_destination_bucket.arn
    prefix     = "firehose-data/"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with a specific region (`us-west-2`).
2. **IAM Role**: An IAM role named `firehose_delivery_stream_role` is created with a trust policy allowing Firehose to assume the role.
3. **IAM Policy**: An IAM policy named `firehose_s3_access_policy` is created to grant Firehose permissions to access the S3 bucket.
4. **IAM Role Policy Attachment**: The policy is attached to the IAM role.
5. **S3 Bucket**: An S3 bucket named `firehose-destination-bucket-<random_suffix>` is created to store the data delivered by Firehose.
6. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream named `firehose-delivery-stream` is created with an extended S3 destination, using the IAM role and S3 bucket created earlier.

