### Description
This Terraform configuration sets up a basic Amazon Kinesis Analytics Application with a CloudWatch log stream. It includes the creation of a Kinesis data stream, a CloudWatch log group, a CloudWatch log stream, an IAM role, an IAM policy, and the Kinesis Analytics application itself. The IAM role is attached with the necessary policy to allow the Kinesis Analytics application to read from the Kinesis stream and write to CloudWatch logs.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kinesis_stream" "kinesis_data_stream" {
  name        = "example-kinesis-stream"
  shard_count = 1
}

resource "aws_cloudwatch_log_group" "analytics_log_group" {
  name = "analytics"
}

resource "aws_cloudwatch_log_stream" "analytics_log_stream" {
  name           = "example-kinesis-application"
  log_group_name = aws_cloudwatch_log_group.analytics_log_group.name
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_analytics_policy" {
  name        = "kinesis-analytics-policy"
  description = "Policy for Kinesis Analytics to access Kinesis stream and CloudWatch logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:DescribeStream",
          "kinesis:SubscribeToShard",
          "logs:PutLogEvents",
          "logs:CreateLogGroup",
          "logs:CreateLogStream"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kinesis_analytics_policy" {
  policy_arn = aws_iam_policy.kinesis_analytics_policy.arn
  role       = aws_iam_role.kinesis_analytics_role.name
}

resource "aws_kinesis_analytics_application" "kinesis_analytics_app" {
  name = "example-kinesis-analytics-app"

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.analytics_log_stream.arn
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
  }

  inputs {
    name_prefix = "example_prefix"

    schema {
      record_columns {
        name     = "COLUMN_1"
        sql_type = "INTEGER"
      }

      record_format {
        mapping_parameters {
          csv {
            record_column_delimiter = ","
            record_row_delimiter    = "|"
          }
        }
      }
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.kinesis_data_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    starting_position_configuration {
      starting_position = "NOW"
    }
  }

  outputs {
    name = "OUTPUT_1"

    schema {
      record_format_type = "CSV"
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.kinesis_data_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  start_application = true
}
```

