### Description
This Terraform program creates a basic Amazon Kendra index with the default Document Metadata Configuration Updates. It includes the necessary IAM role and policy attachment to allow Kendra to function properly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kendra_index" "kendra_index" {
  name = "basic-kendra-index"

  role_arn = aws_iam_role.kendra_role.arn

  document_metadata_configuration_updates {
    name = "_source_uri"
    type = "STRING_VALUE"
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_policy" {
  role       = aws_iam_role.kendra_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKendraFullAccess"
}
```

This configuration sets up an AWS Kendra index named "basic-kendra-index" with a default document metadata configuration update for the `_source_uri` field. It also creates an IAM role named "kendra-role" with the necessary permissions and attaches the "AmazonKendraFullAccess" policy to it.

