### Description

This Terraform program creates an Amazon Kendra index with user group resolution enabled. It includes the necessary IAM role and policy to allow Kendra to resolve user groups. The configuration ensures that all required attributes and dependencies are met for deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Kendra with user group resolution
resource "aws_iam_role" "kendra_user_group_resolution_role" {
  name = "kendra-user-group-resolution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kendra with user group resolution
resource "aws_iam_policy" "kendra_user_group_resolution_policy" {
  name        = "kendra-user-group-resolution-policy"
  description = "Policy for Kendra to resolve user groups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ds:DescribeTrusts",
          "ds:GetTrustRelationship",
          "ds:ListUsers",
          "ds:ListGroups",
          "ds:ListGroupMemberships",
          "ds:ListUserAttributes",
          "ds:ListGroupAttributes"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_kendra_policy_to_role" {
  role       = aws_iam_role.kendra_user_group_resolution_role.name
  policy_arn = aws_iam_policy.kendra_user_group_resolution_policy.arn
}

# Kendra Index with user group resolution configuration
resource "aws_kendra_index" "kendra_index" {
  name     = "my-kendra-index"
  role_arn = aws_iam_role.kendra_user_group_resolution_role.arn

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }
}
```

This Terraform configuration sets up an Amazon Kendra index with user group resolution enabled. It includes an IAM role and policy necessary for Kendra to access AWS Single Sign-On (SSO) for user group resolution. The `aws_kendra_index` resource is configured to use this IAM role and specifies the user group resolution mode as `AWS_SSO`.

