This Terraform configuration sets up a non-alias AWS Route 53 record linked to a private Route 53 zone named "internal.example53.com". The private zone is associated with an AWS VPC named "main". The configuration includes the creation of the VPC, the private Route 53 zone, and a non-alias Route 53 record.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main"
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "internal.example53.com"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "private_zone"
  }
}

resource "aws_route53_record" "non_alias_record" {
  name    = "example"
  type    = "A"
  zone_id = aws_route53_zone.private_zone.zone_id
  ttl     = 300
  records = ["10.0.1.1"]

  tags = {
