### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_name" {
  description = "The name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "cluster_version" {
  description = "The Kubernetes version for the EKS cluster"
  default     = "1.24"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for the EKS cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
}

variable "public_subnet_ids" {
  description = "List of public subnet IDs for the EKS cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef2", "subnet-0123456789abcdef3"]
}

resource "aws_iam_role" "eks_cluster_1" {
  name = "eks-cluster-1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_amazon_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_1.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_1.arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids = concat(var.private_subnet_ids, var.public_subnet_ids)
  }

  depends_on = [
    aws_iam_role_policy_attachment.attach_amazon_eks_cluster_policy
  ]
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`). You can change this to your desired region.
2. **Variables**:
   - `cluster_name`: The name of the EKS cluster.
   - `cluster_version`: The Kubernetes version for the EKS cluster.
   - `private_subnet_ids`: List of private subnet IDs for the EKS cluster.
   - `public_subnet_ids`: List of public subnet IDs for the EKS cluster.
3. **IAM Role**: An IAM role named 'eks-cluster-1' is created with an assume role policy allowing the 'eks.amazonaws.com' service to assume the role.
4. **IAM Role Policy Attachment**: The 'AmazonEKSClusterPolicy' IAM policy is attached to the IAM role.
5. **EKS Cluster**: An EKS cluster is defined with the specified name, version, and associated with the IAM role. The VPC configuration includes both private and public subnet IDs. The cluster creation depends on the policy attachment to ensure proper permissions.

