Below is a complete Terraform HCL program that sets up an AWS provider for a specified region, retrieves the current caller identity, optionally fetches the latest stable ECR image tagged as 'stable' from a specified repository, defines local variables including an image tag, AWS tags, and workspace name, instantiates an EKS module with configurations for cluster setup, IAM policies, instance types, and node count, retrieves information about the created EKS cluster and its authentication data, and configures Helm and Kubernetes providers using the EKS cluster's details for cluster communication.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify the desired AWS region
}

data "aws_caller_identity" "current_identity" {}

# Define local variables
locals {
  image_tag = "stable"  # Default image tag
  aws_tags = {
    Environment = "production"
    Owner       = "terraform-user"
  }
  workspace_name = "dev"
}

# Define an IAM role for EKS
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role-${local.workspace_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# Define an IAM policy for EKS
resource "aws_iam_policy" "eks_cluster_policy" {
  name        = "eks-cluster-policy-${local.workspace_name}"
  description = "Policy for EKS cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeVpcs",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeRouteTables",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeInstanceTypes",
          "iam:ListRoles",
          "iam:GetRole",
          "iam:PassRole",
          "sts:AssumeRole"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = aws_iam_policy.eks_cluster_policy.arn
  role       = aws_iam_role.eks_cluster_role.name
}

# Define subnets for EKS
resource "aws_subnet" "eks_subnet_1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "eks_subnet_2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create an EKS cluster
resource "aws_eks_cluster" "example" {
  name     = "example-eks-cluster-${local.workspace_name}"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.eks_subnet_1.id,
      aws_subnet.eks_subnet_2.id
    ]
  }

  tags = local.aws_tags
}

# Retrieve information about the created EKS cluster
data "aws_eks_cluster" "eks_cluster_info" {
  name = aws_eks_cluster.example.name
}

# Configure Kubernetes provider using the EKS cluster's details
provider "kubernetes" {
  host                   = data.aws_eks_cluster.eks_cluster_info.endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.eks_cluster_info.certificate_authority[0].data)
}

# Configure Helm provider using the EKS cluster's details
provider "helm" {
  kubernetes {
    host                   = data.aws_eks_cluster.eks_cluster_info.endpoint
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.eks_cluster_info.certificate_authority[0].data)
  }
}
```

This Terraform configuration sets up the necessary AWS resources and providers to create an EKS cluster, configure IAM roles and policies, and set up Helm and Kubernetes providers for cluster communication. Make sure to replace placeholder values like VPC IDs and region with actual values from your AWS environment.

