Below is the Terraform HCL program that creates an AWS EKS node group named "example" linked to a specific EKS cluster named "example". The node group is configured with the specified scaling parameters and dependencies on IAM role policy attachments.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for EKS Node Group
resource "aws_iam_role" "eks_node_group_role" {
  name = "eks-node-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach EKS Worker Node Policy
resource "aws_iam_role_policy_attachment" "eks_worker_node_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

# Attach EKS CNI Policy
resource "aws_iam_role_policy_attachment" "eks_cni_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSCNIPolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

# Attach EC2 Container Registry Read Only Policy
resource "aws_iam_role_policy_attachment" "ec2_container_registry_read_only_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node_group_role.name
}

# EKS Cluster
resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_node_group_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with your subnet IDs
  }
}

# EKS Node Group
resource "aws_eks_node_group" "example_eks_node_group" {
  cluster_name    = aws_eks_cluster.example_eks_cluster.name
  node_role_arn   = aws_iam_role.eks_node_group_role.arn
  subnet_ids      = aws_eks_cluster.example_eks_cluster.vpc_config[0].subnet_ids
  node_group_name = "example"

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured with a specific region.
2. **IAM Role for EKS Node Group**: An IAM role is created with an assume role policy that allows EC2 to assume the role.
3. **IAM Role Policy Attachments**: The EKS worker node policy, EKS CNI policy, and EC2 container registry read-only policy are attached to the IAM role.
4. **EKS Cluster**: An EKS cluster is created with the specified name and role ARN. The VPC configuration includes subnet IDs.
5. **EKS Node Group**: An EKS node group is created linked to the EKS cluster. The node group is configured with the specified scaling parameters and update settings.

Make sure to replace the subnet IDs with actual subnet IDs from your AWS account.

