### Description
This Terraform configuration creates an AWS S3 bucket named `my_bucket` and defines an S3 bucket policy to deny access from a specific IP address. The bucket policy includes a version number, an identifier, and a statement that denies all S3 actions for the specified IP address. The `jsonencode` function is used to encode the policy in JSON format.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify the desired AWS region
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = "my_bucket"
  acl    = "private"
}

resource "aws_s3_bucket_policy" "my_bucket_policy" {
  bucket = aws_s3_bucket.my_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "DenyAccessFromSpecificIP"
    Statement = [
      {
        Effect   = "Deny"
        Principal = "*"
        Action   = "s3:*"
        Resource = "${aws_s3_bucket.my_bucket.arn}/*"
        Condition = {
          IpAddress = {
            "aws:SourceIp" = "192.168.1.1/32"  # Replace with the specific IP address to deny
          }
        }
      }
    ]
  })
}
```

