### Description
The Terraform program below creates an AWS AMI for the latest Amazon Linux 2 AMI. It sets the CPU count to 2 and threads per core to 2. The program uses the `aws_ami` resource to fetch the latest Amazon Linux 2 AMI and then creates an EC2 instance with the specified CPU options.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "example" {
  ami           = data.aws_ami.latest_amazon_linux_2.id
  instance_type = "t2.micro"

  cpu_options {
    core_count       = 2
    threads_per_core = 2
  }

  tags = {
    Name = "example-instance"
  }
}
```

