### Description
This Terraform configuration sets up a VPC with public and private subnets. It also defines three EC2 instances within an EC2 placement group for clustering purposes. The VPC is configured with a CIDR block of `10.0.0.0/16`, and the subnets are configured with CIDR blocks of `10.0.1.0/24` for the public subnet and `10.0.2.0/24` for the private subnet. The EC2 instances are launched in the private subnet and use the `t3.micro` instance type.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block       = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"

  tags = {
    Name = "PublicSubnet1"
  }
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "PrivateSubnet1"
  }
}

resource "aws_placement_group" "cluster_placement_group" {
  name     = "ClusterPlacementGroup"
  strategy = "cluster"
}

resource "aws_instance" "ec2_instance_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro in us-west-2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.private_subnet_1.id
  placement_group = aws_placement_group.cluster_placement_group.name

  tags = {
    Name = "EC2Instance1"
  }
}

resource "aws_instance" "ec2_instance_2" {
