### Description
This Terraform configuration sets up an ElastiCache user with IAM integration. It includes the creation of an IAM role, an IAM policy, attaching the policy to the role, and finally creating the ElastiCache user that utilizes the IAM role for authentication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasticache_user_role" {
  name = "elasticache-user-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "elasticache_user_policy" {
  name        = "elasticache-user-policy"
  description = "Policy for ElastiCache user operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:CreateUser",
          "elasticache:DeleteUser",
          "elasticache:DescribeUsers",
          "elasticache:ModifyUser"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elasticache_policy_to_role" {
  policy_arn = aws_iam_policy.elasticache_user_policy.arn
  role       = aws_iam_role.elasticache_user_role.name
}

resource "aws_elasticache_user" "elasticache_user" {
  user_id       = "elasticache-user-id"
  user_name     = "elasticache-user"
  access_string = "on ~* +@all"
  engine        = "redis"

  authentication_mode {
    type = "iam"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `elasticache-user-role` is created with a trust policy allowing ElastiCache to assume the role.
3. **IAM Policy**: An IAM policy named `elasticache-user-policy` is created with permissions to perform various ElastiCache user operations.
4. **Policy Attachment**: The IAM policy is attached to the IAM role.
5. **ElastiCache User**: An ElastiCache user is created with the specified user ID, username, access string, and engine type. The user is configured to use IAM for authentication.

