### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasticsearch_iam_role" {
  name = "elasticsearch-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elasticsearch_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonElastiCacheFullAccess"
  role       = aws_iam_role.elasticsearch_iam_role.name
}

resource "aws_elasticache_user" "elasticache_user" {
  user_id       = "my-user-id"
  user_name     = "my-user-name"
  access_string = "on ~* +@all"
