### Description
This Terraform configuration sets up a highly available Amazon Redshift cluster across two availability zones (`us-east-1a` and `us-east-1b`). It includes the creation of a VPC, subnets, a security group, and the Redshift cluster itself. The Redshift cluster is configured to be multi-AZ for high availability.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "RedshiftVPC"
  }
}

# Create subnets in us-east-1a and us-east-1b
resource "aws_subnet" "subnet_us_east_1a" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "RedshiftSubnet1a"
  }
}

resource "aws_subnet" "subnet_us_east_1b" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "RedshiftSubnet1b"
  }
}

# Create a security group for the Redshift cluster
resource "aws_security_group" "redshift_sg" {
  vpc_id = aws_vpc.redshift_vpc.id
  name   = "redshift-sg"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RedshiftSecurityGroup"
  }
}

# Create an IAM role for Redshift
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "RedshiftIAMRole"
  }
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "redshift_policy" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# Create the Redshift cluster
resource "aws_redshift_cluster" "high_availability_redshift" {
  cluster_identifier = "high-availability-redshift"
  node_type          = "dc2.large"
  cluster_type       = "multi-node"
  number_of_nodes    = 2
  database_name      = "mydb"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  multi_az           = true
  publicly_accessible = false
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  cluster_subnet_group_name = "default"  # Using the default subnet group for simplicity
  iam_roles          = [aws_iam_role.redshift_role.arn]

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }

  tags = {
    Name = "HighAvailabilityRedshiftCluster"
  }
}
```

This configuration sets up a highly available Redshift cluster with the necessary networking and security configurations. The cluster is placed in two different availability zones for redundancy, and an IAM role is created to allow the cluster to access S3.

