### Description
This Terraform configuration creates a Lambda Layer Version resource from a specified payload file (`lambda_layer_payload.zip`). It includes the necessary dependencies such as an IAM role, an S3 bucket, and an S3 object to store the payload. The configuration ensures that all resources are properly created and linked in the correct order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lambda execution
resource "aws_iam_role" "lambda_layer_role" {
  name = "lambda_layer_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lambda execution
resource "aws_iam_policy" "lambda_layer_policy" {
  name        = "lambda_layer_execution_policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_lambda_layer_policy" {
  role       = aws_iam_role.lambda_layer_role.name
  policy_arn = aws_iam_policy.lambda_layer_policy.arn
}

# S3 bucket to store the Lambda layer payload
resource "aws_s3_bucket" "lambda_layer_bucket" {
  bucket = "lambda-layer-payload-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for the S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Upload the Lambda layer payload to S3
resource "aws_s3_object" "lambda_layer_payload" {
  bucket = aws_s3_bucket.lambda_layer_bucket.bucket
  key    = "lambda_layer_payload.zip"
  source = "lambda_layer_payload.zip"
}

# Create a Lambda Layer Version from the S3 object
resource "aws_lambda_layer_version" "lambda_layer_version" {
  layer_name     = "lambda_layer_version"
  s3_bucket      = aws_s3_object.lambda_layer_payload.bucket
  s3_key         = aws_s3_object.lambda_layer_payload.key
  compatible_runtimes = ["python3.8"]
}
```

This configuration sets up the necessary AWS resources to create a Lambda Layer Version from the specified payload file. It includes an IAM role and policy for Lambda execution, an S3 bucket to store the payload, and the Lambda Layer Version itself.

