Below is a complete Terraform HCL program that meets the requirements specified in the prompt. This program sets up an AWS Lambda function named `test_lambda` that will be triggered whenever an EC2 image is created. It includes the necessary IAM roles, policies, S3 bucket, and CloudWatch event rules to achieve this.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Lambda execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lambda execution
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# S3 Bucket to store Lambda code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "lambda-code-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Upload Lambda code to S3 bucket
resource "aws_s3_object" "lambda_code_object" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda_function_payload.zip"
  source = "./path/to/your/lambda_function_payload.zip"  # Update with your Lambda code path
}

# Lambda function
resource "aws_lambda_function" "test_lambda" {
  function_name = "test_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key        = aws_s3_object.lambda_code_object.key
}

# Permission to allow EC2 create event to trigger Lambda
resource "aws_lambda_permission" "allow_ec2_create_trigger" {
  statement_id  = "AllowExecutionFromEC2CreateEvent"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = "arn:aws:events:${var.region}:${data.aws_caller_identity.current.account_id}:rule/EC2ImageCreateRule"
}

# CloudWatch rule to detect EC2 image creation
resource "aws_cloudwatch_event_rule" "ec2_image_create_rule" {
  name        = "EC2ImageCreateRule"
  description = "Triggers on EC2 Image Creation"
  event_pattern = jsonencode({
    "source": ["aws.ec2"],
    "detail-type": ["EC2 Image State Change"],
    "detail": {
      "state": ["available"]
    }
  })
}

# Target to trigger Lambda on EC2 image creation event
resource "aws_cloudwatch_event_target" "trigger_lambda_on_ec2_image_create" {
  rule      = aws_cloudwatch_event_rule.ec2_image_create_rule.name
  target_id = "TriggerTestLambda"
  arn       = aws_lambda_function.test_lambda.arn
}

# Data source to get current AWS account ID
data "aws_caller_identity" "current" {}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured with a specific region (`us-west-2`).
2. **IAM Role and Policy**: An IAM role (`lambda_execution_role`) is created with an assume role policy that allows Lambda to execute. An IAM policy (`lambda_policy`) is created to allow the Lambda function to write logs to CloudWatch. The policy is attached to the IAM role.
3. **S3 Bucket and Object**: An S3 bucket (`lambda_code_bucket`) is created to store the Lambda function code. A random string suffix is appended to the bucket name to ensure uniqueness. The Lambda function code is uploaded to this bucket.
4. **Lambda Function**: The Lambda function (`test_lambda`) is created with the specified handler, runtime, and code location in the S3 bucket.
5. **Lambda Permission**: A permission (`allow_ec2_create_trigger`) is added to allow the CloudWatch event to invoke the Lambda function.
6. **CloudWatch Event Rule and Target**: A CloudWatch event rule (`ec2_image_create_rule`) is created to detect EC2 image creation events. A target (`trigger_lambda_on_ec2_image_create`) is added to trigger the Lambda function when the event occurs.

Make sure to replace `"./path/to/your/lambda_function_payload.zip"` with the actual path to your Lambda function code.

