### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = "ExampleTableName"
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
