To create a SageMaker app configured as a JupyterServer, we need to set up the necessary AWS resources, including a VPC, subnets, an IAM role, a SageMaker domain, and a user profile. Below is a complete Terraform HCL program that accomplishes this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create an IAM role for SageMaker
resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "sagemaker_full_access" {
  role       = aws_iam_role.sagemaker_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}

# Create a SageMaker domain
resource "aws_sagemaker_domain" "example" {
  domain_name = "example-domain"
  auth_mode   = "IAM"
  vpc_id      = aws_vpc.main.id
  subnet_ids  = [aws_subnet.main.id]

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_role.arn

    jupyter_server_app_settings {
      lifecycle_config_arns = []
    }
  }
}

# Create a SageMaker user profile
resource "aws_sagemaker_user_profile" "example" {
  domain_id         = aws_sagemaker_domain.example.id
  user_profile_name = "example-user-profile"

  user_settings {
    execution_role = aws_iam_role.sagemaker_role.arn

    jupyter_server_app_settings {
      lifecycle_config_arns = []
    }
  }
}

# Create a SageMaker app configured as a JupyterServer
resource "aws_sagemaker_app" "sagemaker_jupyter_server" {
  app_name     = "jupyter-server-app"
  app_type     = "JupyterServer"
  domain_id    = aws_sagemaker_domain.example.id
  user_profile_name = aws_sagemaker_user_profile.example.user_profile_name

  resource_spec {
    instance_type = "ml.t3.medium"
  }
}
```

