This Terraform configuration creates a SageMaker Human Task UI resource using an HTML template stored in an S3 bucket. The configuration includes creating an S3 bucket, uploading the HTML template to the bucket, creating an IAM role with necessary permissions, and finally creating the SageMaker Human Task UI.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "sagemaker_human_task_ui_bucket" {
  bucket = "sagemaker-human-task-ui-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "sagemaker_human_task_ui_template" {
  bucket = aws_s3_bucket.sagemaker_human_task_ui_bucket.bucket
  key    = "sagemaker-human-task-ui-template.html"
  content = <<EOF
<h1>
    TEST
</h1>
EOF
}

resource "aws_iam_role" "sagemaker_human_task_ui_role" {
  name = "sagemaker-human-task-ui-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "sagemaker_human_task_ui_policy" {
  name = "sagemaker-human-task-ui-policy"
  role = aws_iam_role.sagemaker_human_task_ui_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.sagemaker_human_task_ui_bucket.arn}",
          "${aws_s3_bucket.sagemaker_human_task_ui_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_sagemaker_human_task_ui" "sagemaker_human_task_ui" {
  human_task_ui_name = "sagemaker-human-task-ui"

  ui_template {
    content = aws_s3_object.sagemaker_human_task_ui_template.content
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Bucket**: An S3 bucket is created to store the HTML template. A random suffix is appended to the bucket name to ensure uniqueness.
3. **S3 Object**: The HTML template is uploaded to the S3 bucket.
4. **IAM Role**: An IAM role is created with a trust policy that allows SageMaker to assume the role.
5. **IAM Role Policy**: A policy is attached to the IAM role that grants SageMaker permissions to access the S3 bucket.
6. **SageMaker Human Task UI**: The SageMaker Human Task UI is created using the uploaded HTML template from the S3 bucket.

