### Description
This Terraform configuration creates a custom Amazon Machine Image (AMI) based on the latest Amazon Linux 2 AMI with specific CPU and core configurations. The process involves copying the latest Amazon Linux 2 AMI, launching a temporary instance with the desired CPU and core settings, and then creating a new AMI from that instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_ami_copy" "latest_amazon_linux_2_ami" {
  name              = "copied-amazon-linux-2"
  source_ami_id     = data.aws_ami.amazon_linux_2.id
  source_ami_region = "us-west-2"
}

resource "aws_instance" "temp_instance" {
  ami           = aws_ami_copy.latest_amazon_linux_2_ami.id
  instance_type = "t2.micro"

  cpu_options {
    core_count       = 2
    threads_per_core = 2
  }

  tags = {
    Name = "temp-instance"
  }
}

resource "aws_ami_from_instance" "customized_ami" {
  name            = "customized-amazon-linux-2"
  source_instance_id = aws_instance.temp_instance.id

  tags = {
    Name = "customized-ami"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Data Source for Latest Amazon Linux 2 AMI**: A data source is used to fetch the latest Amazon Linux 2 AMI ID.
3. **Copy of Latest Amazon Linux 2 AMI**: The `aws_ami_copy` resource creates a copy of the latest Amazon Linux 2 AMI.
4. **Temporary Instance**: An `aws_instance` resource launches a temporary instance using the copied AMI with the specified CPU and core configurations.
5. **Customized AMI**: The `aws_ami_from_instance` resource creates a new AMI from the customized instance.

This configuration ensures that the new AMI has the desired CPU and core settings.

