### Description

This Terraform configuration creates a VPC with a public and private subnet. It also defines an EC2 Fleet consisting of 5 On-Demand and 4 Spot Instances using a launch template. The launch template specifies the use of the latest AWS Linux 2 AMI and sets up the necessary IAM roles and instance profiles for the EC2 Fleet to operate.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

# Create a public subnet
resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

# Create a private subnet
resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone       = "us-west-2b"
  tags = {
    Name = "PrivateSubnet"
  }
}

# Create an IAM role for the EC2 Fleet
resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2-fleet-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM instance profile for the EC2 Fleet
resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ec2-fleet-instance-profile"
  role = aws_iam_role.ec2_fleet_role.name
}

# Create a launch template for the EC2 Fleet
resource "aws_launch_template" "ec2_fleet_launch_template" {
  name          = "ec2-fleet-launch-template"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  }
}

# Data source to get the latest Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# Create an EC2 Fleet
resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.ec2_fleet_launch_template.id
      version            = "$Latest"
    }
    override {
      instance_type     = "t3.micro"
      weighted_capacity = 1
      subnet_id         = aws_subnet.public_subnet.id
    }
    override {
      instance_type     = "t3.micro"
      weighted_capacity = 1
      subnet_id         = aws_subnet.private_subnet.id
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "on-demand"
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
  }

  replace_unhealthy_instances = true
  type                        = "maintain"
  tags = {
    Name = "MainEC2Fleet"
  }
}
```

This configuration sets up the necessary infrastructure to meet the requirements specified in the prompt. It includes creating a VPC, public and private subnets, an IAM role and instance profile, a launch template, and an EC2 Fleet with the specified instance types and counts.

