    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    broker_logs {
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msks_logs_bucket.id
        prefix  = "logs/"
      }
    }
  }

  tags = {
    Name = "Managed MSK Cluster"
  }
}

variable "environment" {
  description = "Environment name for resource tagging"
  default     = "dev"
}
