### Description
This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region and configures it to log to an Amazon Kinesis Firehose delivery stream. The configuration includes the necessary IAM roles and policies to allow the MSK cluster to interact with Kinesis Firehose.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC and subnets
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "subnet_az1" {
  availability_zone = data.aws_availability_zones.azs.names[0]
  cidr_block        = "10.0.1.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_subnet" "subnet_az2" {
  availability_zone = data.aws_availability_zones.azs.names[1]
  cidr_block        = "10.0.2.0/24"
  vpc_id            = aws_vpc.vpc.id
}

resource "aws_subnet" "subnet_az3" {
  availability_zone = data.aws_availability_zones.azs.names[2]
  cidr_block        = "10.0.3.0/24"
  vpc_id            = aws_vpc.vpc.id
}

# Create a security group
resource "aws_security_group" "sg" {
  vpc_id = aws_vpc.vpc.id
}

# Create an IAM role for MSK cluster
resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for MSK cluster
resource "aws_iam_policy" "msk_cluster_policy" {
  name = "msk-cluster-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
  role       = aws_iam_role.msk_cluster_role.name
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_logging_delivery_stream" {
  name        = "msk-logging-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_cluster_role.arn
    bucket_arn = "arn:aws:s3:::msk-logs-bucket"
  }
}

# Create the MSK cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    security_groups = [aws_security_group.sg.id]
  }

  logging_info {
    broker_logs {
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logging_delivery_stream.name
      }
    }
  }
}
```

This Terraform configuration sets up the necessary infrastructure to create a managed MSK cluster in the `us-east-1` region and configure it to log to a Kinesis Firehose delivery stream. The IAM roles and policies ensure that the MSK cluster has the necessary permissions to interact with Kinesis Firehose.

