### Description
This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with JMX Exporter and Node Exporter enabled for monitoring. The configuration includes the necessary IAM roles and policies, as well as the MSK cluster itself with specified broker node group information and monitoring settings.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for MSK Cluster
resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK Cluster
resource "aws_iam_policy" "msk_cluster_policy" {
  name        = "msk-cluster-policy"
  description = "Policy for MSK Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:*",
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "cloudwatch:PutMetricData",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach Policy to IAM Role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
}

# Managed MSK Cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type  = "kafka.m5.large"
    security_groups = ["sg-0123456789abcdef0"]
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}
```

### Notes
- The `client_subnets` and `security_groups` in the `broker_node_group_info` block need to be replaced with actual subnet and security group IDs from your AWS account.
- The `kafka_version` can be updated to a different version if needed.
- Ensure that the IAM policy provided has the necessary permissions for MSK cluster creation and management.

