resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_service_policy.arn
  role       = aws_iam_role.msk_service_role.name
}

# Create the MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.msk_subnet_1.id,
      aws_subnet.msk_subnet_2.id,
      aws_subnet.msk_subnet_3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  tags = {
    Name = "my-msk-cluster"
  }
}
```

This configuration sets up a VPC with three subnets, a security group, an IAM role with the necessary permissions, and finally, a serverless MSK cluster with three broker nodes. Adjust the region, CIDR blocks, and other parameters as needed for your specific environment.

