### Description
This Terraform configuration creates a serverless MSK cluster with 3 broker nodes in the `us-east-1` region. It includes the necessary IAM role and policy to allow the MSK cluster to operate. The configuration also sets up the required VPC and subnets, as well as a security group to control inbound and outbound traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "192.168.0.0/22"
}

# Get available availability zones
data "aws_availability_zones" "azs" {
  state = "available"
}

# Create subnets in different availability zones
resource "aws_subnet" "subnet_az1" {
  availability_zone = data.aws_availability_zones.azs.names[0]
  cidr_block        = "192.168.0.0/24"
  vpc_id            = aws_vpc.main.id
}

resource "aws_subnet" "subnet_az2" {
  availability_zone = data.aws_availability_zones.azs.names[1]
  cidr_block        = "192.168.1.0/24"
  vpc_id            = aws_vpc.main.id
}

resource "aws_subnet" "subnet_az3" {
  availability_zone = data.aws_availability_zones.azs.names[2]
  cidr_block        = "192.168.2.0/24"
  vpc_id            = aws_vpc.main.id
}

# Create a security group
resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM policy for MSK
resource "aws_iam_policy" "msk_serverless_policy" {
  name        = "msk-serverless-policy"
  description = "Policy for MSK serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListNodes",
          "kafka:ListScramSecrets",
          "kafka:ListTagsForResource",
          "kafka:TagResource",
          "kafka:UntagResource"
        ]
        Resource = "*"
      }
    ]
  })
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk_serverless_role" {
  name               = "msk-serverless-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_serverless_policy.arn
  role       = aws_iam_role.msk_serverless_role.name
}

# Create a serverless MSK cluster
resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "msk-serverless-cluster"

  vpc_config {
    subnet_ids         = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
}
```

This configuration sets up a serverless MSK cluster with the necessary IAM role and policy, along with a VPC, subnets, and security group to support the cluster's operation.

