Below is a complete Terraform HCL program that creates an MSK cluster with 3 broker nodes, outputs to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. The MSK cluster is configured with encryption at rest and open monitoring.

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for MSK to deliver logs to Kinesis Firehose
resource "aws_iam_role" "msk_kinesis_firehose_role" {
  name = "msk_kinesis_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK to deliver logs to Kinesis Firehose
resource "aws_iam_policy" "msk_kinesis_firehose_policy" {
  name        = "msk_kinesis_firehose_policy"
  description = "Policy for MSK to deliver logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.msk_logs_bucket.arn,
          "${aws_s3_bucket.msk_logs_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:PutMetricFilter",
          "logs:PutRetentionPolicy"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_msk_kinesis_firehose_policy" {
  role       = aws_iam_role.msk_kinesis_firehose_role.name
  policy_arn = aws_iam_policy.msk_kinesis_firehose_policy.arn
}

# S3 Bucket to store MSK logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
}

# CloudWatch Log Group to store MSK logs
resource "aws_cloudwatch_log_group" "msk_logs_log_group" {
  name = "/aws/msk/logs"
}

# Kinesis Firehose Delivery Stream to deliver MSK logs to S3 and CloudWatch
resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name        = "msk-logs-firehose"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.msk_kinesis_firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_logs_bucket.arn
    prefix     = "logs/msk/"

    buffering_interval = 300
    buffering_size     = 5
    compression_format = "UNCOMPRESSED"
    s3_backup_mode     = "FailedDataOnly"
  }
}

# MSK Cluster with logging enabled
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      "subnet-0123456789abcdef0",
      "subnet-0123456789abcdef1",
      "subnet-0123456789abcdef2"
    ]
    instance_type = "kafka.m5.large"
    security_groups = [
      "sg-0123456789abcdef0"
    ]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.id
        prefix  = "logs/msk/"
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up the required resources and dependencies as described in the prompt. It includes an IAM role and policy for MSK to deliver logs to Kinesis Firehose, an S3 bucket, a CloudWatch log group, a Kinesis Firehose delivery stream, and an MSK cluster with logging enabled. The MSK cluster is configured with encryption at rest and open monitoring.

