### Description
This Terraform configuration creates two AWS VPCs and establishes a peering connection between them. Each VPC is configured with a unique CIDR block to ensure they do not overlap. The VPCs are created in the `us-west-2` region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create the first VPC
resource "aws_vpc" "vpc_1" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "VPC 1"
  }
}

# Create the second VPC
resource "aws_vpc" "vpc_2" {
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "VPC 2"
  }
}

# Establish a peering connection between the two VPCs
resource "aws_vpc_peering_connection" "vpc_peering_connection" {
  vpc_id      = aws_vpc.vpc_1.id
  peer_vpc_id = aws_vpc.vpc_2.id
  auto_accept = true

  tags = {
    Name = "VPC Peering Connection"
  }
}
```

This configuration sets up two VPCs with non-overlapping CIDR blocks and establishes a peering connection between them. The `auto_accept` attribute is set to `true` to automatically accept the peering connection.

