### Description
This Terraform configuration creates a VPC, two subnets within that VPC, and an AWS Neptune cluster using those subnets. The configuration ensures that the subnets are properly associated with the VPC and that the Neptune cluster is correctly configured to use these subnets.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "neptune_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "NeptuneVPC"
  }
}

resource "aws_subnet" "neptune_subnet_1" {
  vpc_id            = aws_vpc.neptune_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "NeptuneSubnet1"
  }
}

resource "aws_subnet" "neptune_subnet_2" {
  vpc_id            = aws_vpc.neptune_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "NeptuneSubnet2"
  }
}

resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = [aws_subnet.neptune_subnet_1.id, aws_subnet.neptune_subnet_2.id]
  tags = {
    Name = "NeptuneSubnetGroup"
  }
}

resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier = "neptune-cluster-demo"
  engine             = "neptune"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  skip_final_snapshot = true
  iam_database_authentication_enabled = true
  apply_immediately = true
  neptune_subnet_group_name = aws_neptune_subnet_group.neptune_subnet_group.name
  tags = {
    Name = "NeptuneCluster"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: Two subnets are created within the VPC, each in a different availability zone (`us-west-2a` and `us-west-2b`).
4. **Neptune Subnet Group**: A Neptune subnet group is created and associated with the two subnets.
5. **Neptune Cluster**: A Neptune cluster is created using the Neptune subnet group, with basic configurations such as backup retention and IAM database authentication enabled.

