Below is the Terraform HCL program that creates an AWS Chime Voice Connector and sets up a configuration to stream media to Amazon Kinesis. The program includes the necessary IAM roles and policies to ensure proper access.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_chime_voice_connector" "voice_connector" {
  name               = "MyChimeVoiceConnector"
  require_encryption = true
}

resource "aws_kinesis_stream" "media_stream" {
  name        = "MyMediaStream"
  shard_count = 1
}

resource "aws_iam_role" "chime_kinesis_role" {
  name = "ChimeKinesisRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "chime_kinesis_policy" {
  name        = "ChimeKinesisPolicy"
  description = "Policy allowing Chime to access Kinesis"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_stream.media_stream.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_chime_kinesis_policy" {
  policy_arn = aws_iam_policy.chime_kinesis_policy.arn
  role       = aws_iam_role.chime_kinesis_role.name
}

resource "aws_chime_voice_connector_streaming" "voice_connector_streaming" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
  data_retention     = 7
  disabled           = false

  media_insights_configuration {
    disabled = false
  }
}
```

This Terraform configuration does the following:
1. Sets up the AWS provider with the region `us-east-1`.
2. Creates an AWS Chime Voice Connector named `MyChimeVoiceConnector`.
3. Creates an Amazon Kinesis stream named `MyMediaStream`.
4. Defines an IAM role named `ChimeKinesisRole` with a trust policy allowing Chime to assume the role.
5. Defines an IAM policy named `ChimeKinesisPolicy` that allows the Chime role to put records into the Kinesis stream.
6. Attaches the IAM policy to the IAM role.
7. Configures streaming for the Chime Voice Connector to send media to the Kinesis stream with a data retention period of 7 days.

