  topic_arn = aws_sns_topic.redshift_notifications.arn
  protocol  = "email"
  endpoint  = "example@example.com"
}

resource "aws_iam_role" "redshift_sns_role" {
  name = "redshift-sns-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_sns_policy" {
  name        = "redshift-sns-policy"
  description = "Policy to allow Redshift to publish to SNS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect = "Allow"
        Resource = aws_sns_topic.redshift_notifications.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_redshift_sns_policy" {
  policy_arn = aws_iam_policy.redshift_sns_policy.arn
  role       = aws_iam_role.redshift_sns_role.name
}
```

