  region = "us-west-2"
}

resource "aws_s3_bucket" "example_payment_bucket" {
  bucket = "example-payment-bucket-${random_string.suffix.result}"
  acl    = "private"
  tags = {
    Name        = "Example Payment Bucket"
    Environment = "Dev"
  }
}

resource "aws_iam_role" "payment_access_role" {
  name = "PaymentAccessRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "payment_access_policy" {
  name        = "PaymentAccessPolicy"
  description = "Policy to allow access to the payment S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.example_payment_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_payment_policy" {
  role       = aws_iam_role.payment_access_role.name
  policy_arn = aws_iam_policy.payment_access_policy.arn
}

resource "aws_s3_bucket_policy" "example_payment_bucket_policy" {
  bucket = aws_s3_bucket.example_payment_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_role.payment_access_role.arn
        }
        Resource = "arn:aws:s3:::${aws_s3_bucket.example_payment_bucket.bucket}/*"
      }
    ]
  })
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Bucket Creation**: An S3 bucket named `example_payment_bucket` is created. The bucket name is made unique by appending a random string suffix.
3. **IAM Role and Policy**: An IAM role named `PaymentAccessRole` is created, which allows EC2 instances to assume the role. An IAM policy named `PaymentAccessPolicy` is created to allow read and write access to the S3 bucket.
4. **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
5. **S3 Bucket Policy**: A bucket policy is applied to the S3 bucket to allow the IAM role to access the bucket.
6. **Random String**: A random string resource is used to ensure the S3 bucket name is unique.

