```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_autograder_policy" {
  name        = "codebuild-autograder-policy"
  description = "Policy for CodeBuild to access GitHub and store results"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "ec2:CreateNetworkInterfacePermission"
        Resource = "arn:aws:ec2:us-east-1:123456789012:network-interface/*"
        Condition = {
          StringEquals = {
            "ec2:Subnet"          = ["subnet-12345678", "subnet-87654321"]
            "ec2:AuthorizedService" = "codebuild.amazonaws.com"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "s3:*"
        Resource = [
          "arn:aws:s3:::autograder-results-bucket",
          "arn:aws:s3:::autograder-results-bucket/*",
        ]
      },
      {
        Effect   = "Allow"
        Action   = [
          "codeconnections:GetConnectionToken",
          "codeconnections:GetConnection"
        ]
        Resource = "arn:aws:codestar-connections:us-east-1:123456789012:connection/guid-string"
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  policy_arn = aws_iam_policy.codebuild_autograder_policy.arn
  role       = aws_iam_role.codebuild_autograder_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  description  = "Autograder project for CS class"
  service_role = aws_iam_role.codebuild_autograder_role.arn

  artifacts {
    type = "S3"
    location = "autograder-results-bucket"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type         = "LINUX_CONTAINER"
  }

  source {
    type     = "GITHUB"
    location = "https://github.com/example/class-repo.git"
  }
}
```

