### Description

This Terraform configuration sets up an infrastructure for an autograder for a CS class. It includes the following components:

1. **AWS S3 Bucket**: To store the results of the autograder.
2. **AWS IAM Role**: For AWS CodeBuild to access necessary resources.
3. **AWS IAM Policy**: Defining the permissions required by the CodeBuild role.
4. **AWS CodeBuild Project**: To run the autograder, pulling code from GitHub and storing results in the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# S3 Bucket to store autograder results
resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "AutograderResultsBucket"
    Environment = "Production"
  }
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_autograder_role" {
  name = "CodeBuildAutograderRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CodeBuildAutograderRole"
    Environment = "Production"
  }
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_autograder_policy" {
  name        = "CodeBuildAutograderPolicy"
  description = "Policy for CodeBuild to access S3 and other resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.autograder_results_bucket.arn,
          "${aws_s3_bucket.autograder_results_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name        = "CodeBuildAutograderPolicy"
    Environment = "Production"
  }
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  policy_arn = aws_iam_policy.codebuild_autograder_policy.arn
  role       = aws_iam_role.codebuild_autograder_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder_codebuild_project" {
  name         = "AutograderCodeBuildProject"
  description  = "CodeBuild project for running the autograder"
  service_role = aws_iam_role.codebuild_autograder_role.arn

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.autograder_results_bucket.bucket}/results"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/your-repo/autograder.git"
    git_clone_depth = 1
  }

  tags = {
    Name        = "AutograderCodeBuildProject"
