### Description
This Terraform program sets up an AWS S3 bucket to store the output of AWS CodeBuild projects. It also creates an AWS CodeBuild project configured to use the S3 bucket for storing build artifacts. The CodeBuild project is set up with specific environment settings and a GitHub source location.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 bucket to store CodeBuild output
resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "codebuild-output-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Generate a random suffix for the S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role to allow access to the S3 bucket
resource "aws_iam_role_policy" "codebuild_s3_access_policy" {
  role   = aws_iam_role.codebuild_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.codebuild_output_bucket.arn,
          "${aws_s3_bucket.codebuild_output_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Create a CodeBuild project
resource "aws_codebuild_project" "student_codebuild_project" {
  name          = "student-codebuild-project"
  description   = "CodeBuild project for students"
  service_role  = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.codebuild_output_bucket.bucket}/artifacts"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/source-location"
    git_clone_depth = 1
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **S3 Bucket**: An S3 bucket named `codebuild-output-bucket-<random_suffix>` is created to store the build artifacts. A random string is appended to ensure the bucket name is unique.
3. **IAM Role**: An IAM role named `codebuild-service-role` is created with a trust policy that allows CodeBuild to assume the role.
4. **IAM Role Policy**: A policy is attached to the IAM role to grant it permissions to access the S3 bucket.
5. **CodeBuild Project**: A CodeBuild project named `student-codebuild-project` is created. It uses the S3 bucket for storing artifacts, specifies the environment settings, and points to a GitHub repository as the source.

