```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC for the autograder environment
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "AutograderVPC"
  }
}

# Subnet within the VPC
resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "AutograderSubnet"
  }
}

# Internet Gateway to allow outbound traffic
resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "AutograderIGW"
  }
}

# Route table for public access
resource "aws_route_table" "autograder_public_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "AutograderPublicRouteTable"
  }
}

# Route to the internet via the Internet Gateway
resource "aws_route" "autograder_internet_route" {
  route_table_id         = aws_route_table.autograder_public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

# Associate the subnet with the route table
resource "aws_route_table_association" "autograder_subnet_route_table_assoc" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_public_route_table.id
}

# Security group to control inbound and outbound traffic
resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "AutograderSG"
  description = "Security group for the autograder environment"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM role for the CodeBuild project
resource "aws_iam_role" "autograder_role" {
  name = "AutograderCodeBuildRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Effect = "Allow"
      },
    ]
  })
}

# IAM policy for the CodeBuild project
resource "aws_iam_policy" "autograder_policy" {
  name = "AutograderCodeBuildPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:CreateNetworkInterfacePermission",
          "s3:*",
          "codeconnections:GetConnectionToken",
          "codeconnections:GetConnection"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "autograder_role_policy_attach" {
  policy_arn = aws_iam_policy.autograder_policy.arn
  role       = aws_iam_role.autograder_role.name
}

# Source credential for GitHub
resource "aws_codebuild_source_credential" "autograder_github_credential" {
  auth_type     = "PERSONAL_ACCESS_TOKEN"
