provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "aws_iam_role" "api_gateway_role" {
  name = "api-gateway-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_access_policy" {
  name        = "s3-access-policy"
  description = "Policy to allow API Gateway to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.cat_pictures_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_role" {
  policy_arn = aws_iam_policy.s3_access_policy.arn
  role       = aws_iam_role.api_gateway_role.name
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
