Below is a complete Terraform HCL program that fulfills the requirements specified in the prompt. It sets up an AWS service that allows users to upload cat pictures and retrieve random cat pictures on demand using AWS DynamoDB, S3, Lambda, API Gateway, and IAM roles.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = "cat-pictures-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "upload_cat_picture_lambda" {
  function_name = "upload-cat-picture-lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = aws_s3_bucket.cat_pictures_bucket.bucket
  s3_key        = "lambda-function-code.zip"

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.cat_pictures_table.name
      S3_BUCKET_NAME      = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_lambda_permission" "upload_cat_picture_permission" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload_cat_picture_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_pictures_api.execution_arn}/*/*"
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"

  integration {
    type            = "AWS_PROXY"
    integration_http_method = "POST"
    uri             = aws_lambda_function.upload_cat_picture_lambda.invoke_arn
  }
}
```

This Terraform configuration sets up the necessary AWS resources to handle the upload of cat pictures. It includes a DynamoDB table to store metadata about the pictures, an S3 bucket to store the actual images, an IAM role and policy for the Lambda function, a Lambda function to handle uploads, and an API Gateway to expose the upload endpoint.

