  resource_id   = aws_api_gateway_resource.caas_cat_resource.id
  http_method   = "PUT"
  authorization = "NONE"
}

# API Gateway Integration for GET
resource "aws_api_gateway_integration" "caas_get_integration" {
  rest_api_id          = aws_api_gateway_rest_api.caas_api.id
  resource_id          = aws_api_gateway_resource.caas_cat_resource.id
