### Description
This Terraform program provisions an EC2 instance and sets up a daily backup at midnight using AWS Backup. The program includes the following resources:
1. **AWS Backup Vault**: A vault to store the backup recovery points.
2. **AWS Backup Plan**: A plan that defines the backup schedule and target vault.
3. **AWS Backup Selection**: A selection that specifies which resources (in this case, the EC2 instance) to include in the backup plan.
4. **AWS IAM Role**: An IAM role that AWS Backup will assume to perform the backup operations.
5. **AWS EC2 Instance**: The EC2 instance to be backed up.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "aws-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role
resource "aws_iam_role_policy" "backup_policy" {
  name = "aws-backup-policy"
  role = aws_iam_role.backup_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:DescribeInstances",
          "ec2:TerminateInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:CreateTags"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Create a backup vault
resource "aws_backup_vault" "backup_vault" {
  name = "my-backup-vault"
}

# Create a backup plan
resource "aws_backup_plan" "backup_plan" {
  name = "daily-backup-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight UTC

    lifecycle {
      delete_after = 30  # Retain backups for 30 days
    }
  }
}

# Create a backup selection
resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id
  name         = "my-backup-selection"

  resources = [
    aws_instance.ec2_instance.arn
  ]
}

# Create an EC2 instance
resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for t3.micro
  instance_type = "t3.micro"

  tags = {
    Name = "MyBackupInstance"
  }
}
```

### Explanation
- **IAM Role and Policy**: An IAM role is created for AWS Backup with the necessary permissions to perform backup operations on EC2 instances.
- **Backup Vault**: A backup vault is created to store the backup recovery points.
- **Backup Plan**: A backup plan is defined with a rule that schedules daily backups at midnight UTC.
- **Backup Selection**: The backup selection specifies the EC2 instance to be included in the backup plan.
- **EC2 Instance**: An EC2 instance is provisioned using a sample AMI ID for a t3.micro instance type.

This configuration ensures that the EC2 instance is backed up daily at midnight using AWS Backup.

