### Description
This Terraform configuration sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge and AWS Lambda. The configuration includes creating an IAM role and policy for the Lambda function, defining the Lambda function itself, setting up an EventBridge rule to trigger the Lambda function daily, and granting the necessary permissions for EventBridge to invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Basic Execution Policy for Lambda
resource "aws_iam_policy" "lambda_basic_execution_policy" {
  name        = "lambda_basic_execution_policy"
  description = "Basic policy for Lambda execution."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the Basic Execution Policy to the Lambda Execution Role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_basic_execution_policy.arn
}

# Lambda Function to Run Code Daily
resource "aws_lambda_function" "daily_code_runner" {
  function_name = "daily_code_runner"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  filename         = "path/to/your/deployment/package.zip"
  source_code_hash = filebase64sha256("path/to/your/deployment/package.zip")

  environment {
    variables = {
      NAME = "World"
    }
  }
}

# EventBridge Rule to Trigger Lambda Function Daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"
}

# Allow EventBridge to Invoke the Lambda Function
resource "aws_lambda_permission" "allow_eventbridge_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule_rule.arn
}

# Target the Lambda Function from the EventBridge Rule
resource "aws_cloudwatch_event_target" "target_lambda_from_rule" {
  rule      = aws_cloudwatch_event_rule.daily_schedule_rule.name
  target_id = "RunDailyCode"
  arn       = aws_lambda_function.daily_code_runner.arn
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role and Policy**: An IAM role (`lambda_execution_role`) is created with a trust policy allowing Lambda to assume the role. A basic execution policy (`lambda_basic_execution_policy`) is created to allow logging to CloudWatch. The policy is attached to the IAM role.
3. **Lambda Function**: A Lambda function (`daily_code_runner`) is defined with the necessary permissions and a deployment package. The function is triggered by an EventBridge rule.
4. **EventBridge Rule**: An EventBridge rule (`daily_schedule_rule`) is created with a cron expression to trigger the Lambda function daily at 7 UTC.
5. **Permissions and Targets**: Permissions are granted to EventBridge to invoke the Lambda function, and the Lambda function is targeted by the EventBridge rule.

