### Description

This Terraform configuration sets up the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront and AWS S3. The configuration includes:

1. **AWS S3 Bucket**: To store the video content.
2. **IAM Role and Policy**: For CloudFront origin access identity.
3. **CloudFront Origin Access Identity**: To restrict access to the S3 bucket.
4. **S3 Bucket Policy**: To allow CloudFront access to the S3 bucket.
5. **CloudFront Distribution**: To distribute the video content globally.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = "video-content-bucket-logs-${random_string.bucket_suffix.result}"
    target_prefix = "logs/"
  }

  tags = {
    Name = "Video Content Bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "cloudfront-origin-access-identity-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_origin_access_identity_policy" {
  name        = "cloudfront-origin-access-identity-policy"
  description = "Policy for CloudFront origin access identity"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.video_content_bucket.arn}/*"
        Principal = {
          AWS = aws_iam_role.cloudfront_origin_access_identity_role.arn
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_cloudfront_policy_to_role" {
  policy_arn = aws_iam_policy.cloudfront_origin_access_identity_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

resource "aws_cloudfront_origin_access_identity" "video_content_origin_access_identity" {
  comment = "Origin access identity for video content bucket"
}

resource "aws_s3_bucket_policy" "bucket_policy_for_cloudfront" {
  bucket = aws_s3_bucket.video_content_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Resource = "${aws_s3_bucket.video_content_bucket.arn}/*"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.iam_arn
        }
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Distribution"
  default_root_object = "index.html"

  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id   = "myS3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "Video Streaming Distribution"
  }
}
```

This Terraform configuration sets up the necessary AWS resources to distribute video content globally using CloudFront and S3. The S3 bucket is configured with versioning and logging, and the CloudFront distribution is set up to serve the content securely.

