Below is a complete Terraform HCL program that sets up the infrastructure for a video streaming site using AWS CloudFront, AWS Route53, and AWS S3. The program includes the necessary IAM roles and policies to ensure secure access between the services.

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

# S3 Bucket to store video content
resource "aws_s3_bucket" "video_streaming_bucket" {
  bucket = "video-streaming-${var.domain_name}"
  acl    = "private"

  tags = {
    Name = "Video Streaming Bucket"
  }
}

# IAM Role for CloudFront Origin Access Identity
resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "cloudfront-origin-access-identity-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy to allow CloudFront to access S3 bucket
resource "aws_iam_policy" "cloudfront_origin_access_identity_policy" {
  name        = "cloudfront-origin-access-identity-policy"
  description = "Policy to allow CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.video_streaming_bucket.arn}/*"
        ]
        Principal = {
          AWS = aws_iam_role.cloudfront_origin_access_identity_role.arn
        }
      }
    ]
  })
}

# Attach policy to IAM role
resource "aws_iam_role_policy_attachment" "attach_cloudfront_policy_to_role" {
  policy_arn = aws_iam_policy.cloudfront_origin_access_identity_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

# CloudFront Origin Access Identity
resource "aws_cloudfront_origin_access_identity" "video_streaming_oai" {
  comment = "Origin Access Identity for CloudFront to access S3"
}

# S3 Bucket Policy to allow CloudFront OAI access to S3 bucket
resource "aws_s3_bucket_policy" "video_streaming_bucket_policy" {
  bucket = aws_s3_bucket.video_streaming_bucket.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.video_streaming_bucket.arn}/*"
        ]
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.video_streaming_oai.iam_arn
        }
      }
    ]
  })
}

# CloudFront Distribution to serve video content globally
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming CloudFront Distribution"
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.video_streaming_bucket.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_identity.video_streaming_oai.cloudfront_access_identity_path
    origin_id                = "myS3Origin"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  logging_config {
    include_cookies = false
    bucket          = "mylogs.s3.amazonaws.com"
    prefix          = "myprefix"
  }

  aliases = [var.domain_name]

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Environment = "production"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Route53 Hosted Zone for domain registration
resource "aws_route53_zone" "video_streaming_domain_zone" {
  name = var.domain_name

  tags = {
    Name = "Video Streaming Domain Zone"
  }
}

# DNS Record to map domain to CloudFront distribution
resource "aws_route53_record" "video_streaming_domain_record" {
  name    = var.domain_name
  type    = "A"
  zone_id = aws_route53_zone.video_streaming_domain_zone.zone_id
  ttl     = 300

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_distribution.hosted_zone_id
    evaluate_target_health = true
  }
}
```

This Terraform configuration sets up an S3 bucket to store video content, an IAM role and policy to allow CloudFront to access the S3 bucket, a CloudFront distribution to serve the video content globally, and a Route53 hosted zone and record to map the domain to the CloudFront distribution.

