    Name = "video-streaming-server-1"
  }
}

resource "aws_instance" "video_streaming_server_2" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID for t2.micro
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.video_streaming_subnet_public.id
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "video-streaming-server-2"
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  }

  tags = {
    Name = "video-streaming-listener"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_server_1_attachment" {
  target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  target_id        = aws_instance.video_streaming_server_1.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "video_streaming_server_2_attachment" {
