LLM Output #0:
### Description

This Terraform configuration sets up the infrastructure for a video streaming site with load balancing using AWS services. It includes:

1. **AWS VPC**: A Virtual Private Cloud to host the infrastructure.
2. **AWS Subnets**: Public and private subnets within the VPC.
3. **AWS Internet Gateway**: To allow internet access to the public subnet.
4. **AWS Route Table**: For routing internet traffic through the Internet Gateway.
5. **AWS Security Group**: For web traffic on the public subnet.
6. **AWS EC2 Instance**: An EC2 instance in the public subnet for serving video content.
7. **AWS Application Load Balancer (ALB)**: To distribute incoming traffic across multiple servers.
8. **AWS Route53 Hosted Zone and Record**: To map a domain to the load balancer.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a Virtual Private Cloud (VPC)
resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "video-streaming-vpc"
  }
}

# Create a public subnet within the VPC
resource "aws_subnet" "video_streaming_subnet_public" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "video-streaming-public-subnet"
  }
}

# Create a private subnet within the VPC
resource "aws_subnet" "video_streaming_subnet_private" {
  vpc_id                  = aws_vpc.video_streaming_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  tags = {
    Name = "video-streaming-private-subnet"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "video_streaming_igw" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  tags = {
    Name = "video-streaming-igw"
  }
}

# Create a route table for the public subnet
resource "aws_route_table" "video_streaming_public_route_table" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.video_streaming_igw.id
  }
  tags = {
    Name = "video-streaming-public-route-table"
  }
}

# Associate the public subnet with the public route table
resource "aws_route_table_association" "video_streaming_public_subnet_association" {
  subnet_id      = aws_subnet.video_streaming_subnet_public.id
  route_table_id = aws_route_table.video_streaming_public_route_table.id
}

# Create a security group for web traffic on the public subnet
resource "aws_security_group" "video_streaming_sg_web" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  name   = "video-streaming-sg-web"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "video-streaming-sg-web"
  }
}

# Launch an EC2 instance in the public subnet for serving video content
resource "aws_instance" "video_streaming_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.video_streaming_subnet_public.id
  security_groups = [aws_security_group.video_streaming_sg_web.name]
  tags = {
    Name = "video-streaming-server"
  }
}

# Create an Application Load Balancer
resource "aws_lb" "video_streaming_load_balancer" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.video_streaming_subnet_public.id]
  security_groups    = [aws_security_group.video_streaming_sg_web.id]
  tags = {
    Name = "video-streaming-alb"
  }
}

# Create a target group for the load balancer
resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
  tags = {
    Name = "video-streaming-target-group"
  }
}

# Create a listener for the load balancer
resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_load_balancer.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  }
  tags = {
    Name = "video-streaming-listener"
  }
}

# Register the EC2 instance with the target group
resource "aws_lb_target_group_attachment" "video_streaming_target_group_attachment" {
  target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  target_id        = aws_instance.video_streaming_server.id
  port             = 80
}

# Create a Route53 hosted zone for the domain
resource "aws_route53_zone" "video_streaming_domain_zone" {
  name = "example.com"
  tags = {
    Name = "video-streaming-domain-zone"
  }
}

# Create a DNS record in Route53 to point the domain to the load balancer
resource "aws_route53_record" "video_streaming_domain_record" {
  zone_id = aws_route53_zone.video_streaming_domain_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  alias {
    name                   = aws_lb.video_streaming_load_balancer.dns_name
    zone_id                = aws_lb.video_streaming_load_balancer.zone_id
    evaluate_target_health = true
  }
}
```

