Below is a complete Terraform HCL program that sets up a VPC with public subnets and security groups for database access. It also creates a PostgreSQL database instance within the VPC, accessible and secured by a designated security group.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"
  tags = {
    Name = "PublicSubnet1"
  }
}

resource "aws_security_group" "database_access_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "DatabaseAccessSG"
  description = "Security group for database access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseAccessSG"
  }
}

resource "aws_db_instance" "postgres_db" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "postgres"
  engine_version = "13.4"
  name = "mydb"
  username = "admin"
  password = "password"
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.database_access_sg.id]
  skip_final_snapshot = true

  tags = {
    Name = "PostgresDB"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = [aws_subnet.public_subnet_1.id]

  tags = {
    Name = "DefaultSubnetGroup"
  }
}
```

This Terraform configuration does the following:
1. Sets up a VPC with a CIDR block of `10.0.0.0/16`.
2. Creates a public subnet within the VPC with a CIDR block of `10.0.1.0/24` and maps public IP addresses on launch.
3. Defines a security group for database access, allowing inbound traffic on port 5432 (PostgreSQL) from any IP address.
4. Creates a PostgreSQL database instance within the VPC, using the defined subnet group and security group.
5. Tags all resources for easy identification in the AWS Management Console.

