Below is a complete Terraform HCL program that provisions a secure PostgreSQL database instance within a specified AWS VPC, leveraging AWS services like RDS, subnets, and KMS for encryption. It sets up a custom parameter group for PostgreSQL settings, and a security group to manage access. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. The database instance is configured with "pgsnapshot" as the final snapshot identifier.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "database_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "database_subnet_public_1" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "database_subnet_public_2" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "database_security_group" {
  vpc_id = aws_vpc.database_vpc.id
  name   = "database_security_group"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "database_parameter_group" {
  family = "postgres13"

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  parameter {
    name  = "shared_buffers"
    value = "256MB"
  }
}

resource "aws_kms_key" "database_kms_key" {
  description             = "KMS key for PostgreSQL database encryption"
  deletion_window_in_days = 7
}

resource "aws_db_instance" "database_instance" {
  instance_class       = "db.t3.medium"
  engine               = "postgres"
  engine_version       = "13.7"
  allocated_storage    = 20
  username             = "admin"
  password             = "securepassword"
  db_name              = "mydatabase"
  multi_az             = true
  storage_encrypted    = true
  kms_key_id           = aws_kms_key.database_kms_key.arn
  vpc_security_group_ids = [aws_security_group.database_security_group.id]
  db_subnet_group_name = aws_db_subnet_group.database_subnet_group.name
  final_snapshot_identifier = "pgsnapshot"
}

resource "aws_db_subnet_group" "database_subnet_group" {
  name       = "database_subnet_group"
  subnet_ids = [aws_subnet.database_subnet_public_1.id, aws_subnet.database_subnet_public_2.id]
}
```

This Terraform configuration creates a VPC, two public subnets, a security group, a parameter group, a KMS key, and a PostgreSQL RDS instance with the specified configurations. The security group allows inbound traffic on port 5432 for PostgreSQL, and the RDS instance is encrypted using the KMS key. The final snapshot identifier is set to "pgsnapshot".

