Below is a complete Terraform HCL program that sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a MySQL RDS instance with public accessibility, linked to the defined subnets and security group, outputting the database endpoint for connectivity.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_a_cidr_block" {
  description = "CIDR block for the public subnet in Availability Zone A"
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr_block" {
  description = "CIDR block for the public subnet in Availability Zone B"
  default     = "10.0.2.0/24"
}

variable "db_instance_class" {
  description = "Instance class for the MySQL RDS instance"
  default     = "db.t3.micro"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_public_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_a_cidr_block
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_public_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_b_cidr_block
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "db-security-group"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "mysql_rds_instance" {
  instance_class       = var.db_instance_class
  engine               = "mysql"
  engine_version       = "8.0"
  allocated_storage    = 20
  username             = "admin"
  password             = "password"
  db_name              = "mydatabase"
  publicly_accessible  = true
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  db_subnet_group_name = "default"  # Using the default subnet group for simplicity
}

output "db_endpoint" {
  value = aws_db_instance.mysql_rds_instance.endpoint
}
```

This Terraform configuration sets up the required AWS resources and ensures that the RDS instance is publicly accessible with the appropriate security group rules. The outputs section provides the database endpoint for connectivity.

