### Description
This Terraform configuration sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. It specifies details such as the engine version, instance size, storage, and associated networking resources. The backup retention period is set to 5 days, and the backup window is configured from 3 AM to 6 AM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a custom VPC
resource "aws_vpc" "custom_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "CustomVPC"
  }
}

# Create a subnet within the custom VPC
resource "aws_subnet" "custom_subnet" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "CustomSubnet"
  }
}

# Create a security group for the PostgreSQL database
resource "aws_security_group" "postgres_sg" {
  name        = "PostgreSQLSecurityGroup"
  description = "Allow PostgreSQL traffic"
  vpc_id      = aws_vpc.custom_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "PostgreSQLSecurityGroup"
  }
}

# Create a PostgreSQL database instance within the custom subnet and security group
resource "aws_db_instance" "postgres_db" {
  instance_class       = "db.t3.micro"
  engine               = "postgres"
  engine_version       = "13.7"
  allocated_storage    = 20
  username             = "admin"
  password             = "securepassword"
  db_name              = "mydatabase"
  backup_retention_period = 5
  backup_window        = "03:00-06:00"
  vpc_security_group_ids = [aws_security_group.postgres_sg.id]
  db_subnet_group_name = aws_db_subnet_group.default.name
  skip_final_snapshot  = true

  tags = {
    Name = "PostgreSQLDBInstance"
  }
}

# Create a DB subnet group
resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = [aws_subnet.custom_subnet.id]

  tags = {
    Name = "DefaultDBSubnetGroup"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC Creation**: A custom VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: A subnet is created within the custom VPC with a CIDR block of `10.0.1.0/24`.
4. **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address (`0.0.0.0/0`). Egress traffic is allowed to any IP address.
5. **PostgreSQL Database Instance**: A PostgreSQL database instance is created with the specified engine version, instance class, storage, and networking configurations. The backup retention period is set to 5 days, and the backup window is from 3 AM to 6 AM.
6. **DB Subnet Group**: A DB subnet group is created to associate the database instance with the custom subnet.

