Below is a complete Terraform HCL program that sets up a PostgreSQL database instance in AWS, specifying details like engine version, instance size, storage, and associated networking resources within a custom VPC and subnet. The database allows major version upgrades, automatically does minor version upgrades, and is not publicly accessible.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_class" {
  description = "The instance class of the RDS instance"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "The allocated storage for the RDS instance"
  default     = 20
}

variable "db_engine_version" {
  description = "The engine version to use"
  default     = "13.7"
}

variable "db_name" {
  description = "The name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  default     = "securepassword"
}

resource "aws_vpc" "database_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "database_subnet" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "database_sg" {
  vpc_id = aws_vpc.database_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "database_subnet_group" {
  name       = "database-subnet-group"
  subnet_ids = [aws_subnet.database_subnet.id]
}

resource "aws_db_instance" "database_instance" {
  instance_class           = var.db_instance_class
  allocated_storage        = var.db_allocated_storage
  engine                   = "postgres"
  engine_version           = var.db_engine_version
  name                     = var.db_name
  username                 = var.db_username
  password                 = var.db_password
  db_subnet_group_name     = aws_db_subnet_group.database_subnet_group.name
  vpc_security_group_ids   = [aws_security_group.database_sg.id]
  publicly_accessible      = false
  allow_major_version_upgrade = true
  auto_minor_version_upgrade = true
}
```

This Terraform configuration creates a VPC, a subnet within the VPC, a security group to control access to the database, a DB subnet group, and a PostgreSQL database instance. The database instance is configured to allow major version upgrades, automatically perform minor version upgrades, and is not publicly accessible.

