Below is a complete Terraform HCL program that sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "Availability zones for the subnets"
  default     = ["us-west-2a", "us-west-2b"]
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "aurora-sg"
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS Aurora cluster"
  default     = "aurora-cluster"
}

variable "db_proxy_name" {
  description = "Name of the RDS proxy"
  default     = "aurora-proxy"
}

variable "db_username" {
  description = "Username for the RDS Aurora cluster"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS Aurora cluster"
  default     = "securepassword123"
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block = var.vpc_cidr_block
  tags = {
    Name = "aurora-vpc"
  }
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = var.availability_zones[0]
  tags = {
    Name = "aurora-subnet-1"
  }
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = var.availability_zones[1]
  tags = {
    Name = "aurora-subnet-2"
  }
}

resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = var.security_group_name

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.security_group_name
  }
}

resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "aurora_proxy_policy" {
  name        = "aurora-proxy-policy"
  description = "Policy for Aurora proxy to access the Aurora cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_aurora_proxy_policy" {
  policy_arn = aws_iam_policy.aurora_proxy_policy.arn
  role       = aws_iam_role.aurora_proxy_role.name
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"

  tags = {
    Name = "aurora-credentials"
  }
}

resource "aws_rds_cluster" "aurora_cluster" {
  engine                = "aurora-mysql"
  engine_version        = "8.0.mysql_aurora.3.02.0"
  cluster_identifier    = var.db_cluster_identifier
  master_username       = var.db_username
  master_password       = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name  = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  tags = {
    Name = var.db_cluster_identifier
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]

  tags = {
    Name = "aurora-subnet-group"
  }
}

resource "aws_db_proxy" "aurora_proxy" {
  name                   = var.db_proxy_name
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = var.db_username
  }

  tags = {
    Name = var.db_proxy_name
  }
}
```

