### Description
This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the creation of a VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The backup retention period for the RDS cluster is set to 5 days, and the preferred backup window is from 7 AM to 9 AM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "AuroraVPC"
  }
}

# Create subnets
resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "AuroraSubnet1"
  }
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "AuroraSubnet2"
  }
}

# Create a security group
resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = "aurora_sg"
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "AuroraSG"
  }
}

# Create an IAM role for the RDS Proxy
resource "aws_iam_role" "aurora_rds_proxy_role" {
  name = "AuroraRDSProxyRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy for the RDS Proxy
resource "aws_iam_policy" "aurora_rds_proxy_policy" {
  name        = "AuroraRDSProxyPolicy"
  description = "Policy for RDS Proxy to access Aurora cluster"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds-db:connect"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the RDS Proxy role
resource "aws_iam_role_policy_attachment" "attach_aurora_rds_proxy_policy" {
  policy_arn = aws_iam_policy.aurora_rds_proxy_policy.arn
  role       = aws_iam_role.aurora_rds_proxy_role.name
}

# Create a DB subnet group
resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora_subnet_group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  tags = {
    Name = "AuroraSubnetGroup"
  }
}

# Create an Aurora RDS cluster
resource "aws_rds_cluster" "aurora_cluster" {
  engine                = "aurora-mysql"
  engine_version        = "8.0.mysql_aurora.3.02.0"
  cluster_identifier    = "aurora-cluster-demo"
  master_username       = "admin"
  master_password       = "securepassword123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name  = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  tags = {
    Name = "AuroraCluster"
  }
}

# Create Aurora RDS cluster instances
resource "aws_rds_cluster_instance" "aurora_instance_1" {
  identifier         = "aurora-instance-1"
  cluster_identifier = aws_rds_cluster.aurora_cluster.id
  instance_class     = "db.t3.medium"
  engine             = aws_rds_cluster.aurora_cluster.engine
  engine_version     = aws_rds_cluster.aurora_cluster.engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  tags = {
    Name = "AuroraInstance1"
  }
}

resource "aws_rds_cluster_instance" "aurora_instance_2" {
  identifier         = "aurora-instance-2"
  cluster_identifier = aws_rds_cluster.aurora_cluster.id
  instance_class     = "db.t3.medium"
  engine             = aws_rds_cluster.aurora_cluster.engine
  engine_version     = aws_rds_cluster.aurora_cluster.engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  tags = {
    Name = "AuroraInstance2"
  }
}

# Create a Secrets Manager secret for Aurora credentials
resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"
  description = "Credentials for Aurora cluster"
  tags = {
    Name = "AuroraCredentials"
  }
}

# Create an RDS Proxy
resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_rds_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = aws_rds_cluster.aurora_cluster.master_username
  }

  tags = {
    Name = "AuroraProxy"
  }
}
```

This Terraform configuration sets up the required infrastructure for an AWS RDS Aurora MySQL cluster with a proxy, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage.

