### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lightsail_postgres_role" {
  name = "lightsail-postgres-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_postgres_policy" {
  name        = "lightsail-postgres-policy"
  description = "Policy for managing Lightsail PostgreSQL database"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lightsail:CreateRelationalDatabase",
          "lightsail:DeleteRelationalDatabase",
          "lightsail:UpdateRelationalDatabase",
          "lightsail:GetRelationalDatabase",
          "lightsail:GetRelationalDatabases"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_postgres_policy" {
