provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

resource "aws_lightsail_instance" "lightsail_instance" {
  name              = "my-lightsail-instance"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_3_0"
}

resource "aws_lightsail_disk" "disk_1" {
  name              = "disk-1"
  size_in_gb        = 20
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_lightsail_disk" "disk_2" {
  name              = "disk-2"
  size_in_gb        = 20
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_lightsail_disk_attachment" "disk_1_attachment" {
  disk_name     = aws_lightsail_disk.disk_1.name
  instance_name = aws_lightsail_instance.lightsail_instance.name
  disk_path     = "/dev/xvdf"
}

resource "aws_lightsail_disk_attachment" "disk_2_attachment" {
  disk_name     = aws_lightsail_disk.disk_2.name
  instance_name = aws_lightsail_instance.lightsail_instance.name
  disk_path     = "/dev/xvdg"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **Availability Zones Data Source**: This data source fetches available availability zones that meet the specified criteria.
3. **Lightsail Instance**: An AWS Lightsail instance is created with a specified name, availability zone, blueprint ID, and bundle ID.
4. **Lightsail Disks**: Two AWS Lightsail disks are created, each with a specified name, size in GB, and availability zone.
5. **Disk Attachments**: Two disk attachments are created to attach the disks to the Lightsail instance. Each attachment specifies the disk name, instance name, and disk path.

This configuration ensures that the disks are attached to the instance after both the instance and the disks have been created.

