Below is the Terraform HCL program that creates a Lightsail resource access to an S3 bucket. This program includes the necessary IAM roles, policies, and S3 bucket configuration to ensure that Lightsail can access the specified S3 bucket.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lightsail_bucket_access_role" {
  name = "lightsail-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_bucket_access_policy" {
  name        = "lightsail-s3-access-policy"
  description = "Policy to allow Lightsail to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_bucket_access_policy" {
  policy_arn = aws_iam_policy.lightsail_bucket_access_policy.arn
  role       = aws_iam_role.lightsail_bucket_access_role.name
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket"
}

resource "aws_s3_bucket_policy" "bucket_access_policy" {
  bucket = aws_s3_bucket.example_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.lightsail_bucket_access_role.arn
        }
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}
```

This Terraform configuration does the following:
1. Defines an AWS provider with a specified region.
2. Creates an IAM role (`lightsail_bucket_access_role`) that Lightsail can assume.
3. Defines an IAM policy (`lightsail_bucket_access_policy`) that grants permissions to access the S3 bucket.
4. Attaches the IAM policy to the IAM role.
5. Creates an S3 bucket (`example_bucket`).
6. Sets up an S3 bucket policy (`bucket_access_policy`) that allows the IAM role to perform specified actions on the bucket.

This setup ensures that the Lightsail resource has the necessary permissions to access the specified S3 bucket.

