}

resource "aws_sns_topic" "s3_glacier_vault_notification_topic" {
  name = "s3-glacier-vault-notification-topic"
}

resource "aws_iam_role" "s3_glacier_vault_notification_role" {
  name = "s3-glacier-vault-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_glacier_vault_notification_policy" {
  name        = "s3-glacier-vault-notification-policy"
  description = "Policy allowing S3 Glacier to publish to the SNS topic"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect = "Allow"
        Resource = aws_sns_topic.s3_glacier_vault_notification_topic.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_glacier_vault_notification_policy_to_role" {
  policy_arn = aws_iam_policy.s3_glacier_vault_notification_policy.arn
  role       = aws_iam_role.s3_glacier_vault_notification_role.name
}

resource "aws_glacier_vault" "my_s3_glacier_vault" {
  name = "my-s3-glacier-vault"

  notification {
    sns_topic = aws_sns_topic.s3_glacier_vault_notification_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }
}
```

