This Terraform configuration creates an S3 Glacier vault and applies a Vault Lock to it. The Vault Lock enforces compliance and immutability on the data stored in the Glacier vault. The configuration includes the necessary resources and dependencies as inferred from the prompt.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify the desired AWS region
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-sns-topic"
}

data "aws_iam_policy_document" "glacier_access_policy" {
  statement {
    sid    = "add-read-only-perm"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "glacier:InitiateJob",
      "glacier:GetJobOutput",
    ]

    resources = ["arn:aws:glacier:${var.region}:${var.account_id}:vaults/${aws_glacier_vault.my_archive.name}"]
  }
}

resource "aws_glacier_vault" "my_archive" {
  name = "MyArchive"

  notification {
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  access_policy = data.aws_iam_policy_document.glacier_access_policy.json

  tags = {
    Test = "MyArchive"
  }
}

resource "aws_glacier_vault_lock" "example" {
  complete_lock = true
  policy        = data.aws_iam_policy_document.vault_lock_policy.json
  vault_name    = aws_glacier_vault.my_archive.name
}

data "aws_iam_policy_document" "vault_lock_policy" {
  statement {
    sid    = "VaultLockPolicy"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "glacier:DeleteArchive",
      "glacier:DeleteVaultAccessPolicy",
      "glacier:DeleteVaultNotifications",
      "glacier:RemoveTagsFromVault",
      "glacier:SetDataRetrievalPolicy",
      "glacier:UploadArchive",
      "glacier:WriteJobOutput",
    ]

    resources = ["arn:aws:glacier:${var.region}:${var.account_id}:vaults/${aws_glacier_vault.my_archive.name}"]
  }
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "account_id" {
  description = "The AWS account ID"
  default     = "123456789012"  # Replace with your actual AWS account ID
}
```

