### Description
This Terraform configuration creates an Application Load Balancer named `test-lb-tf` with specified security groups and subnets. The load balancer is not internal and has deletion protection enabled. The configuration includes the creation of a security group and two subnets in different Availability Zones.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a security group for the load balancer
resource "aws_security_group" "test_lb_sg" {
  name        = "test-lb-sg"
  description = "Security group for the test load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create two subnets in different Availability Zones
resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create the Application Load Balancer
resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.test_lb_sg.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_2.id
  }

  enable_deletion_protection = true

  tags = {
    Name = "test-lb-tf"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with the region `us-west-2`.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Security Group**: A security group is created for the load balancer, allowing HTTP traffic on port 80 from any IP address.
- **Subnets**: Two subnets are created in different Availability Zones (`us-west-2a` and `us-west-2b`) within the VPC.
- **Application Load Balancer**: An Application Load Balancer is created with the specified name, security group, and subnets. Deletion protection is enabled, and the load balancer is not internal.

