LLM Output #0:
### Description
This Terraform configuration creates an internal-facing Application Load Balancer (ALB) with specified private IP addresses for its subnets. The ALB is configured to listen on HTTP and forward traffic to a target group. The configuration includes the necessary resources such as the load balancer, listener, target group, and listener rule.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_lb" "internal_load_balancer" {
  name               = "internal-alb"
  internal           = true
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id            = aws_subnet.subnet1.id
    private_ipv4_address = "10.0.1.15"
  }

  subnet_mapping {
    subnet_id            = aws_subnet.subnet2.id
    private_ipv4_address = "10.0.2.15"
  }
}

resource "aws_lb_target_group" "target_group_web" {
  name     = "web-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.internal_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group_web.arn
  }
}

resource "aws_lb_listener_rule" "rule_forward_to_target_group" {
  listener_arn = aws_lb_listener.listener_http.arn
  priority     = 100

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group_web.arn
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnets**: A VPC and two subnets are created within the VPC.
- **Load Balancer**: An internal-facing Application Load Balancer is created with specified private IP addresses for its subnets.
- **Target Group**: A target group is created to manage the backend web servers.
- **Listener**: An HTTP listener is defined for the load balancer.
- **Listener Rule**: A listener rule is created to forward requests to the target group based on the host header.

