### Description
This Terraform configuration creates an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The configuration includes the creation of the load balancer, the target group, and a listener that routes traffic to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a security group for the load balancer
resource "aws_security_group" "lb_sg" {
  name        = "lb-security-group"
  description = "Security group for the load balancer"
  vpc_id      = "vpc-12345678"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a subnet for the load balancer
resource "aws_subnet" "lb_subnet" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create the Application Load Balancer
resource "aws_lb" "my_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.lb_subnet.id]

  tags = {
    Name = "MyApplicationLoadBalancer"
  }
}

# Create a target group for the load balancer
resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-12345678"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "MyTargetGroup"
  }
}

# Create a listener for the load balancer
resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.my_target_group.arn
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Security Group**: A security group is created for the load balancer to allow HTTP traffic on port 80.
3. **Subnet**: A subnet is created within the specified VPC for the load balancer.
4. **Load Balancer**: An Application Load Balancer is created with the specified security group and subnet.
5. **Target Group**: A target group is created to register EC2 instances with the load balancer.
6. **Listener**: A listener is created to forward traffic from port 80 to the target group.

This configuration ensures that the load balancer, target group, and listener are correctly set up to forward traffic to EC2 instances.

