### Description

This Terraform configuration sets up an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). The ALB listens on port 80 and forwards traffic to the NLB target group, which in turn forwards traffic to a backend target group associated with the NLB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create two subnets in different availability zones
resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Create an Application Load Balancer
resource "aws_lb" "application_load_balancer" {
  name               = "app-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  tags = {
    Name = "Application Load Balancer"
  }
}

# Create a target group for the Network Load Balancer
resource "aws_lb_target_group" "nlb_target_group" {
  name     = "nlb-target-group"
  port     = 443
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    port     = 443
    protocol = "TCP"
  }

  tags = {
    Name = "NLB Target Group"
  }
}

# Create a listener for the Application Load Balancer
resource "aws_lb_listener" "application_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_target_group.arn
  }

  tags = {
    Name = "Application Listener"
  }
}

# Create a Network Load Balancer
resource "aws_lb" "network_load_balancer" {
  name               = "nlb"
  internal           = false
  load_balancer_type = "network"
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  tags = {
    Name = "Network Load Balancer"
  }
}

# Create a target group for the backend services
resource "aws_lb_target_group" "backend_target_group" {
  name     = "backend-target-group"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    port     = 80
    protocol = "TCP"
  }

  tags = {
    Name = "Backend Target Group"
  }
}

# Create a listener for the Network Load Balancer
resource "aws_lb_listener" "network_listener" {
  load_balancer_arn = aws_lb.network_load_balancer.arn
  port              = 443
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.backend_target_group.arn
  }

  tags = {
    Name = "Network Listener"
  }
}
```

This configuration creates the necessary resources to set up an ALB that forwards traffic to an NLB, which then forwards traffic to backend services. The VPC and subnets are also created to support the load balancers.

