LLM Output #0:
### Description
This Terraform program creates an Application Load Balancer (ALB) with a listener on port 80. The listener includes a rule that uses an Authenticate-OIDC action for authentication. Additionally, an IAM role and policy are created to support the OIDC authentication process.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  security_groups    = ["sg-0123456789abcdef0"]

  enable_deletion_protection = true

  tags = {
    Environment = "production"
  }
}

resource "aws_lb_listener" "listener_80" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = "https://example.com/authorization_endpoint"
      client_id              = "client_id"
      client_secret          = "client_secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/token_endpoint"
      user_info_endpoint     = "https://example.com/user_info_endpoint"
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.front_end.arn
  }
}

resource "aws_lb_target_group" "front_end" {
  name     = "front-end-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_iam_role" "oidc_auth_role" {
  name = "oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = "your_cognito_pool_id"
          }
          ForAnyValue:StringLike = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "oidc_auth_policy" {
  name = "oidc-auth-policy"
  role = aws_iam_role.oidc_auth_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}
```

### Notes
- Replace `"subnet-0123456789abcdef0"`, `"subnet-0fedcba9876543210"`, `"sg-0123456789abcdef0"`, and `"vpc-0123456789abcdef0"` with your actual subnet, security group, and VPC IDs.
- Replace `"your_cognito_pool_id"` with your actual Cognito pool ID.
- Ensure that the OIDC provider URLs (`authorization_endpoint`, `token_endpoint`, `user_info_endpoint`) are correctly configured for your identity provider.
- Adjust the IAM policy as necessary for your specific use case.

