### Description
This Terraform program creates an AWS EFS (Elastic File System) with a lifecycle policy applied to it. The lifecycle policy specifies that files should transition to the Infrequent Access (IA) storage class after 30 days.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  tags = {
    Name = "MyEFSFileSystem"
  }

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }
}

# Example of creating a mount target for the EFS file system
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example_subnet" {
  vpc_id            = aws_vpc.example_vpc.id
  availability_zone = "us-west-2a"
  cidr_block        = "10.0.1.0/24"
}

resource "aws_security_group" "example_sg" {
  vpc_id = aws_vpc.example_vpc.id
  name   = "efs-sg"

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.example_subnet.id
  security_groups = [aws_security_group.example_sg.id]
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with the region `us-west-2`.
2. **EFS File System**: An EFS file system is created with a lifecycle policy that transitions files to IA storage class after 30 days.
3. **VPC, Subnet, and Security Group**: These resources are created to support mounting the EFS file system.
4. **EFS Mount Target**: A mount target is created for the EFS file system in the specified subnet and security group.

This configuration ensures that the EFS file system is created with the specified lifecycle policy and is ready to be mounted in a VPC.

