  }
}

resource "aws_backup_vault" "backup_vault" {
  name = "efs-backup-vault"
}

resource "aws_backup_plan" "backup_plan" {
  name = "efs-backup-plan"

  rule {
    rule_name         = "daily-efs-backup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)" // Daily backup at midnight UTC
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id
  name         = "efs-backup-selection"

  resources = [
    aws_efs_file_system.efs_file_system.arn
  ]
}

resource "aws_iam_role" "backup_role" {
  name = "efs-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "backup_policy" {
  name = "efs-backup-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "backup:StartBackupJob",
          "backup:GetBackupVaultAccessPolicy",
          "backup:GetBackupVaultNotifications",
          "backup:DescribeBackupVault",
          "backup:ListRecoveryPointsByBackupVault",
          "backup:CreateBackupVault",
          "backup:DeleteBackupVault",
          "backup:PutBackupVaultAccessPolicy",
          "backup:PutBackupVaultNotifications",
          "backup:UpdateRecoveryPointLifecycle",
          "backup:DescribeRecoveryPoint",
          "backup:ListBackupJobs",
          "backup:ListBackupVaults",
          "backup:ListProtectedResourcesByBackupVault",
          "backup:GetBackupPlanFromBackupVault",
          "backup:GetBackupPlan",
          "backup:GetRecoveryPointRestoreMetadata",
          "backup:RestoreBackup",
          "backup:CopyBackup",
          "backup:TagResource",
          "backup:UntagResource",
          "backup:ListTags"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_backup_policy" {
  policy_arn = aws_iam_policy.backup_policy.arn
  role       = aws_iam_role.backup_role.name
}
```

This Terraform configuration sets up an EFS file system, a backup vault, a backup plan, and a backup selection. It also creates an IAM role and policy to allow the backup process to access the necessary AWS services. The backup plan is scheduled to run daily at midnight UTC.

